(()=>{'use strict';
const P=GTA_PRODUCTS,C=GTA_CATEGORIES,M=GTAModel,$=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],money=n=>new Intl.NumberFormat('ru-RU').format(n)+' ₽',esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),KEY='gta.store.demo.v6';
let pricingScenario='volume',detailSelections={},lastCatalogRoute='/catalog',scrollPositions={};let state=M.initial(),storageOK=true,useBonus=false,detail={v:0,color:'',qty:1},filter={category:'all',q:'',sort:'featured',favorites:false},toastTimer,renderedRoute='',pendingConfirmation=null,checkoutBusy=false;
try{const raw=localStorage.getItem(KEY)||localStorage.getItem('gta.store.demo.v5');if(raw){try{state=M.sanitize(JSON.parse(raw),P);}catch{state=M.initial();}}}catch(e){storageOK=false;}
function storageWarning(){if($('.storage-warning'))return;const n=document.createElement('div');n.className='storage-warning';n.textContent='Хранилище браузера недоступно. Демо работает в этой вкладке; после перезагрузки корзина и история могут сброситься.';$('.demo-strip').after(n);}
function save(){state.pricingScenario=pricingScenario;try{localStorage.setItem(KEY,JSON.stringify(state));}catch(e){storageOK=false;storageWarning();}updateHeader();}
pricingScenario=state.pricingScenario||'volume';if(!storageOK)storageWarning();
const totals=()=>M.totals(state,P,useBonus,pricingScenario);
function updateHeader(){$('#cart-count').textContent=state.cart.reduce((n,x)=>n+x.qty,0);$('.account-link span').textContent=state.member?'Мой гараж':'Кабинет';}
function toast(msg,link=''){clearTimeout(toastTimer);const el=$('#toast');el.innerHTML=esc(msg)+(link?`<a href="${link}">Открыть ↗</a>`:'');el.hidden=false;rewriteLinks();toastTimer=setTimeout(()=>el.hidden=true,4500);}
function bread(label){return `<div class="breadcrumbs"><a href="#/">Главная</a><span>/</span><span>${esc(label)}</span></div>`;}
const tag=(text,cls='')=>`<span class="badge ${cls}">${text}</span>`;
const colors={'Графит':'#272438','Бирюза':'#51d8cb','Коралл':'#ff706f','Лаванда':'#a48aff'};
function visual(p){if(['rack','art'].includes(p.visual))return `<img class="visual" src="assets/${p.visual}.png" alt="Концепт: ${esc(p.name)}" loading="lazy">`;
const car=`<svg viewBox="0 0 250 100" aria-hidden="true"><path d="M14 64 L37 51 L71 43 L98 20 L155 20 L184 43 L222 53 L237 66 L232 79 L17 79Z" fill="#51d8cb"/><path d="M82 43 L104 25 L151 25 L176 43Z" fill="#18172d"/><path d="M43 55 L218 57" stroke="#a48aff" stroke-width="4"/><circle cx="64" cy="77" r="17" fill="#18172d" stroke="#ff706f" stroke-width="6"/><circle cx="193" cy="77" r="17" fill="#18172d" stroke="#ff706f" stroke-width="6"/></svg>`;
const objs={neon:'<div class="neon-object"><img src="assets/logo.png" alt=""></div>',poster:`<div class="poster-object">${car}</div>`,nfc:'<div class="nfc-object"><img src="assets/logo.png" alt=""><div class="fake-qr" aria-hidden="true"></div><small>ДЕКОРАТИВНЫЙ КОД</small></div>',clock:'<div class="clock-object"><div class="clock-ticks"><span>12</span></div><img src="assets/logo.png" alt=""></div>',calendar:'<div class="calendar-object"><strong>1</strong><strong>8</strong><small>OCT / GTA</small></div>',print:'<div class="print-object"><img src="assets/logo.png" alt=""></div>'};
const extras={
wallrack:'<div class="wallrack-object"><i></i><i></i><i></i><i></i></div>',
tools:'<div class="tools-object"><i></i><i></i><i></i><b></b></div>',
brushes:'<div class="brushes-object"><i></i><i></i><i></i><b></b></div>',
towels:'<div class="towels-object"><b></b><i></i><i></i></div>',
qrwall:'<div class="qrwall-object"><img src="assets/logo.png" alt=""><div class="fake-qr"></div><small>ДЕКОРАТИВНЫЙ КОД</small></div>',
navigation:'<div class="navigation-object"><b>ПРИЁМКА ↗</b><b>ДЕТЕЙЛИНГ →</b><b>ВЫДАЧА ↗</b></div>',
bay:'<div class="bay-object"><small>DETAILING ZONE</small><strong>01</strong><span>GTA GARAGE</span></div>',
brandposter:'<div class="brandposter-object"><img src="assets/logo.png" alt=""><span>ТВОЙ ЛОГОТИП.<br>ТВОЁ ПРОСТРАНСТВО.</span></div>',
tray:'<div class="tray-object"><img src="assets/logo.png" alt=""></div>',
cardholder:'<div class="cardholder-object"><div><img src="assets/logo.png" alt=""></div><b>GARAGE CREW</b></div>',
stickers:'<div class="stickers-object">'+Array(6).fill('<span><img src="assets/logo.png" alt=""></span>').join('')+'</div>',
carecards:'<div class="carecards-object"><img src="assets/logo.png" alt=""><b>ПОСЛЕ<br>ДЕТЕЙЛИНГА.</b><i></i><i></i><i></i></div>'
};Object.assign(objs,extras);
return `<div class="visual ${p.visual}" role="img" aria-label="Концепт: ${esc(p.name)}">${objs[p.visual]||''}</div>`;}
function productCard(p){const fav=state.favorites.includes(p.id);return `<article class="product-card"><div style="position:relative"><a class="product-image" href="#/product/${p.id}" aria-label="${esc(p.name)} — подробнее">${visual(p)}<span class="product-tag">${p.tag}</span><span class="visual-caption">КОНЦЕПТ ИЗДЕЛИЯ</span></a><button class="favorite ${fav?'selected':''}" data-favorite="${p.id}" aria-label="${fav?'Убрать из':'Добавить в'} избранное: ${esc(p.name)}" aria-pressed="${fav}">${fav?'♥':'♡'}</button></div><div class="product-info"><a href="#/product/${p.id}"><h3>${p.name}</h3></a><p>${p.subtitle}</p><div class="product-price-row"><div><strong>от ${money(p.price)}</strong><small>ДЕМОЦЕНА · НЕ ПРАЙС-ЛИСТ</small></div><button class="quick-add" data-quick="${p.id}" aria-label="Добавить ${esc(p.name)} в базовом варианте">+</button></div></div></article>`;}
function productsGrid(list){return list.length?list.map(productCard).join(''):`<div class="empty-state" style="grid-column:1/-1"><div class="empty-symbol">∅</div><h2>Пока ничего.</h2><p>Попробуй другой запрос или сбрось фильтры. В демокаталоге ${P.length} концептов изделий.</p><button class="button secondary" data-action="reset-filters">Сбросить фильтры</button></div>`;}
function catalog(){return `<section class="page">${bread('Магазин')}<div class="page-head"><div><div class="section-kicker">GTA / МАГАЗИН С ХАРАКТЕРОМ</div><h1>ОСНАЩЕНИЕ И ДЕКОР<br><em>ТВОЕЙ СТУДИИ.</em></h1><p>Оснащение, которое помогает работать. Декор, который говорит за тебя.</p></div><div class="catalog-head-aside"><span class="count-mark">${P.length.toString().padStart(2,'0')}</span><a href="#/kit" class="text-link">Собрать комплект ↗</a></div></div>${routePath().includes('ref=')?'<div class="ref-arrival">Ты открыл пример реферальной ссылки GTA. Это демонстрация: переходы не отслеживаются, приглашение и вознаграждение не зарегистрированы.</div>':''}<div class="catalog-banner"><div class="catalog-banner-copy"><div class="section-kicker">СОЗДАЁМ ПОД ТВОЮ СТУДИЮ</div><h2>ОДИН СТИЛЬ.<br>СОТНИ ДЕТАЛЕЙ.</h2><p>Логотип студии, любимые цвета, свой автомобильный сюжет. Выбери основу, а детали оставь для согласования.</p></div><img class="banner-art" src="assets/art.png" alt="Концепт автоарта в студии"></div><div class="catalog-toolbar"><label class="search-box"><span aria-hidden="true">⌕</span><input id="catalog-search" type="search" placeholder="Найти стойку, панно, свет…" value="${esc(filter.q)}" aria-label="Поиск по товарам"></label><button class="wishlist-toggle ${filter.favorites?'active':''}" data-action="toggle-favorites" aria-pressed="${filter.favorites}">♡ Избранное</button><select id="catalog-sort" aria-label="Порядок товаров"><option value="featured">Сначала рекомендуемые</option><option value="price-up">Сначала дешевле</option><option value="price-down">Сначала дороже</option><option value="name">По названию</option></select></div><div class="catalog-layout"><aside class="filters"><h3>КАТЕГОРИИ</h3>${C.map(([id,name])=>`<button class="filter-button ${filter.category===id?'active':''}" data-filter="${id}" aria-pressed="${filter.category===id}"><span>${name}</span><small>${id==='all'?P.length:P.filter(p=>p.category===id).length}</small></button>`).join('')}<div class="filter-note"><b>Важное о каталоге</b>Все цены примерные для демонстрации расчётов. Изображения — концепты. Наличие и характеристики не утверждены.<br><a href="#/fiverox">Ищешь плёнку? → FIVEROX</a><br>GTA плёнку не продаёт.</div></aside><div><div class="products-topline"><span id="result-count"></span><span>ПОД ТВОЙ ЛОГОТИП / ПОД ТВОЁ ПРОСТРАНСТВО</span></div><div class="product-grid" id="catalog-grid"></div></div></div></section>`;}
function persistFilters(){const q=new URLSearchParams();if(filter.category!=='all')q.set('category',filter.category);if(filter.q)q.set('q',filter.q);if(filter.sort!=='featured')q.set('sort',filter.sort);if(filter.favorites)q.set('favorites','1');const ref=new URLSearchParams(routePath().split('?')[1]||'').get('ref');if(ref)q.set('ref',ref);lastCatalogRoute='/catalog'+(q.size?'?'+q.toString():'');currentRouteKey=lastCatalogRoute;try{history.replaceState(null,'',routeURL(lastCatalogRoute));}catch{}}
function updateCatalog(){if(!$('#catalog-grid'))return;let list=P.filter(p=>(filter.category==='all'||p.category===filter.category)&&(!filter.favorites||state.favorites.includes(p.id))&&`${p.name} ${p.subtitle} ${p.tag}`.toLocaleLowerCase('ru').includes(filter.q.toLocaleLowerCase('ru').trim()));if(filter.sort==='price-up')list.sort((a,b)=>a.price-b.price);if(filter.sort==='price-down')list.sort((a,b)=>b.price-a.price);if(filter.sort==='name')list.sort((a,b)=>a.name.localeCompare(b.name,'ru'));$('#catalog-grid').innerHTML=productsGrid(list);$('#result-count').textContent=`НАЙДЕНО: ${list.length} ИЗ ${P.length}`;$('#catalog-sort').value=filter.sort;$$('[data-filter]').forEach(b=>{b.classList.toggle('active',b.dataset.filter===filter.category);b.setAttribute('aria-pressed',b.dataset.filter===filter.category)});persistFilters();const wish=$('.wishlist-toggle');wish.classList.toggle('active',filter.favorites);wish.setAttribute('aria-pressed',filter.favorites);rewriteLinks();}
function productPage(id){const p=P.find(p=>p.id===id);if(!p)return notFound();detail=detailSelections[id]||{v:0,color:p.colors[0],qty:1};detailSelections[id]=detail;return `<section class="page"><div class="breadcrumbs"><a href="#/">Главная</a><span>/</span><a href="#${esc(lastCatalogRoute)}">Магазин</a><span>/</span><span>${p.name}</span></div><div class="detail-grid"><div class="detail-gallery"><div class="detail-main">${visual(p)}<span class="visual-caption">ВИЗУАЛЬНЫЙ КОНЦЕПТ / ИТОГОВЫЙ МАКЕТ СОГЛАСУЕТСЯ</span></div><div class="gallery-note"><span>01 / КОНЦЕПЦИЯ ИЗДЕЛИЯ</span><span>GTA · GARAGE TOOLS & ART</span></div></div><div class="detail-info" data-product="${p.id}"><div class="section-kicker">${p.tag} / GTA COLLECTION</div><h1>${p.name}</h1><p class="lede">${p.subtitle}</p>${tag('Под индивидуальный проект')}<div class="detail-price" id="detail-price">${money(p.price+p.variants[detail.v][1])}</div><div class="demo-price">Пример цены для демо. Не является предложением о продаже.</div><span class="option-label">Исполнение</span><div class="variant-group">${p.variants.map(([v,price],i)=>`<button class="variant ${i===detail.v?'selected':''}" data-variant="${i}" aria-pressed="${i===detail.v}">${v}</button>`).join('')}</div><span class="option-label">Цвет концепта</span><div class="color-group">${p.colors.map((c,i)=>`<button class="color-swatch ${c===detail.color?'selected':''}" data-color="${c}" aria-pressed="${c===detail.color}"><i style="--swatch:${colors[c]}"></i>${c}</button>`).join('')}</div><div class="buy-row"><div class="quantity"><button data-detail-qty="-1" aria-label="Уменьшить количество">−</button><output id="detail-quantity" aria-live="polite">${detail.qty}</output><button data-detail-qty="1" aria-label="Увеличить количество">+</button></div><button class="button" data-add-detail="${p.id}">В демо-корзину <span>↗</span></button></div><p class="availability">Визуализация не меняется при выборе цвета и варианта. Выбор сохраняется в корзине. Финальные характеристики, цена и срок изготовления утверждаются отдельно.</p><div class="detail-accordion"><details open><summary>О предмете</summary><p>${p.details}</p></details><details><summary>Характеристики концепта</summary>${p.specs.map(([k,v])=>`<div class="spec-row"><span>${k}</span><b>${v}</b></div>`).join('')}</details><details><summary>Заказ, доставка и персонализация</summary><p>В этой версии можно протестировать сборку корзины и локальное оформление. Реальные способы доставки, оплаты, сроки и условия персонализации пока не подключены. Файлы логотипа не загружаются.</p><a class="text-link" href="#/legal">Что нужно утвердить до запуска ↗</a><br><br></details></div></div></div><section class="related"><div class="section-title-row"><h2>ДОБАВЬ ХАРАКТЕРА.</h2><a class="text-link" href="#/catalog">Весь каталог ↗</a></div><div class="product-grid">${recommendationsFor(id).map(([pid])=>P.find(p=>p.id===pid)).map(productCard).join('')}</div></section></section>`;}
function summary(checkout=false){const t=totals();return `<aside class="summary-card"><h2>Твой комплект</h2><div class="threshold-box"><div><b>${t.eligible?'Порог 50 000 ₽ достигнут':`До порога 50 000 ₽: ${money(t.thresholdNeeded)}`}</b><small>Проект: −10% на товары при сумме от 50 000 ₽</small></div><div class="threshold-meter"><i style="width:${Math.min(100,t.subtotal/50000*100)}%"></i></div><p>${pricingScenario==='volume'?(t.eligible?'В выбранном демосценарии применены 10%.':'Скидка появится в этом демосценарии при достижении порога.'):'Показан другой сценарий. Скидки не суммируются.'}</p></div><label class="scenario-label">Сравнить условия · проект<select id="pricing-scenario"><option value="volume" ${pricingScenario==='volume'?'selected':''}>10% от 50 000 ₽</option><option value="referral" ${pricingScenario==='referral'?'selected':''}>20% по приглашению · отдельно</option><option value="loyalty" ${pricingScenario==='loyalty'?'selected':''}>Бонусная карта · отдельно</option><option value="none" ${pricingScenario==='none'?'selected':''}>Без скидок и бонусов</option></select></label><p class="scenario-note">Совмещение 10%, 20% и бонусов ещё не согласовано. Поэтому здесь сценарии сравниваются отдельно. Реальных акций нет.</p><div class="summary-row"><span>Товары · ${t.count} шт.</span><b>${money(t.subtotal)}</b></div>${t.commercialDiscount?`<div class="summary-row discount"><span>Сценарная скидка ${Math.round(t.discountRate*100)}%</span><b>− ${money(t.commercialDiscount)}</b></div>`:''}<div class="summary-row"><span>Доставка</span><span>не рассчитана</span></div>${t.pointsAllowed?(state.member?`<label class="bonus-toggle"><input id="use-bonus" type="checkbox" ${useBonus?'checked':''} ${!t.maxSpend?'disabled':''}><span>Использовать демобонусы<small>Доступно ${state.points} · В этой корзине до ${t.maxSpend}<br>Проект правил: не более 20% товаров</small></span></label>`:`<div class="summary-hint">Бонусы можно протестировать в <a href="#/account?next=${checkout?'checkout':'cart'}">демокабинете</a>. Реального входа нет.</div>`):'<p class="summary-hint">В этом сценарии демобонусы не списываются и не начисляются.</p>'}${t.spent?`<div class="summary-row discount"><span>Списание · демо</span><b>− ${money(t.spent)}</b></div>`:''}<div class="summary-row total"><span>Итого за товары</span><b>${money(t.total)}</b></div><div class="summary-hint">${state.member&&t.pointsAllowed?`+${t.earned} баллов в ожидании после демооформления. `:''}Доставка не включена: тарифы не утверждены.</div>${checkout?'<button class="button" type="submit" form="checkout-form" id="checkout-submit">Создать демо-заказ ↗</button>':'<a class="button" href="#/checkout">Протестировать оформление ↗</a>'}<p class="fineprint">Суммы вымышленные. Никакой оплаты, акцепта оферты или отправки заказа продавцу. Порог 50 000 ₽ трактуется как рабочий вариант до подтверждения.</p></aside>`;}
function cartPage(){if(!state.cart.length)return `<section class="page">${bread('Корзина')}<div class="empty-state"><div class="empty-symbol">+</div><h1>ЗДЕСЬ НАЧИНАЕТСЯ<br>ТВОЙ КОМПЛЕКТ.</h1><p>Пока корзина пустая. Добавь стойку, автоарт или небольшой акцент для студии.</p><a href="#/catalog" class="button">Выбрать первый предмет ↗</a></div></section>`;return `<section class="page">${bread('Корзина')}<div class="page-head"><div><div class="section-kicker">GTA / ТВОЙ КОМПЛЕКТ</div><h1>КОРЗИНА<span style="color:#a48aff">.</span></h1><p>Проверь детали. Всё должно быть по-твоему.</p></div><span class="badge">Сохраняется в этом браузере</span></div><div class="cart-layout"><div><div class="cart-labels"><span>ПРЕДМЕТ / ИСПОЛНЕНИЕ</span><span>КОЛИЧЕСТВО / ДЕМОСУММА</span></div>${state.cart.map((x,i)=>{const p=P.find(p=>p.id===x.id),unit=p.price+p.variants[x.v][1];return `<article class="cart-row"><a class="cart-thumb" href="#/product/${p.id}" aria-label="${p.name}">${visual(p)}</a><div><a href="#/product/${p.id}"><h3>${p.name}</h3></a><div class="cart-options"><select data-cart-variant="${i}" aria-label="Исполнение ${p.name}">${p.variants.map(([name],v)=>`<option value="${v}" ${v===x.v?'selected':''}>${name}</option>`).join('')}</select><select data-cart-color="${i}" aria-label="Цвет ${p.name}">${p.colors.map(c=>`<option ${c===x.color?'selected':''}>${c}</option>`).join('')}</select></div><p>${money(unit)} за шт. · демо</p><button class="remove" data-remove="${i}" aria-label="Удалить ${p.name}, ${p.variants[x.v][0]}, ${x.color}">Убрать</button></div><div class="quantity"><button data-cart-qty="${i}" data-delta="-1" aria-label="Уменьшить количество ${p.name}" ${x.qty===1?'disabled':''}>−</button><output>${x.qty}</output><button data-cart-qty="${i}" data-delta="1" aria-label="Увеличить количество ${p.name}" ${x.qty===99?'disabled':''}>+</button></div><div class="cart-line-price">${money(unit*x.qty)}<small>Демоценa</small></div></article>`}).join('')}<div class="cart-bottom"><button class="link-button" data-action="show-recommendations">Подобрать дополнение ↗</button><a href="#/catalog" class="text-link">← Продолжить выбирать</a><button class="link-button" data-action="clear-cart">Очистить корзину</button></div><p class="page-end-note">В корзине нет плёнки. Партнёрские программы FIVEROX оформляются отдельной заявкой после запуска.</p></div><div id="summary-wrap">${summary()}</div></div></section>`;}
function checkoutPage(){if(!state.cart.length)return cartPage();return `<section class="page">${bread('Демооформление')}<div class="page-head"><div><div class="section-kicker">GTA / ПОСЛЕДНИЙ ШАГ В ДЕМО</div><h1>ПОЧТИ В ГАРАЖЕ<span style="color:#a48aff">.</span></h1><p>Пройдём сценарий заказа на вымышленных данных.</p></div></div><div class="checkout-steps"><a href="#/cart">01 / Корзина</a><span class="active">02 / Демооформление</span><span>03 / Результат</span></div><div class="cart-layout"><form id="checkout-form" novalidate><section class="form-section"><h2>01. Демо-получатель</h2><div class="field-grid"><label class="field">Имя · пример<input readonly value="Демо-мастер GTA" aria-label="Демоимя"></label><label class="field">Студия · пример<input readonly value="Демо-студия 01" aria-label="Демостудия"></label></div><p class="form-note">Имя, телефон, email и адрес настоящего клиента здесь не вводятся. Авторизация и отправка персональных данных не подключены.</p></section><section class="form-section"><h2>02. Как мог бы приехать заказ</h2><div class="radio-options"><label class="radio-option"><input type="radio" name="delivery" value="pickup" checked><span>Самовывоз · демо<small>Место и условия выдачи не заданы.</small></span></label><label class="radio-option"><input type="radio" name="delivery" value="delivery"><span>Доставка · демо<small>Перевозчик и стоимость не заданы.</small></span></label></div><p class="form-note">Выбор меняет только сценарий в локальной истории. Адрес не запрашивается; доставки и бесплатного самовывоза сайт не обещает.</p></section><section class="form-section"><h2>03. Вместо оплаты — проверка сценария</h2><div class="radio-option"><input type="radio" checked disabled aria-label="Демонстрационный режим"><span>Без оплаты<small>Банковские карты, переводы и платёжный шлюз отсутствуют.</small></span></div><label class="check-label"><input type="checkbox" id="demo-confirm" required><span>Понимаю, что это демонстрация: цены и правила не утверждены, реальный заказ не создаётся, оплата не производится. Это не акцепт оферты.</span></label><p class="error-note" id="checkout-error" role="alert" hidden></p></section></form><div id="summary-wrap">${summary(true)}</div></div></section>`;}
function successPage(id){const o=state.orders.find(o=>o.id===id);if(!o)return notFound();return `<section class="page">${bread('Результат демонстрации')}<div class="success-screen"><div class="success-mark">✓</div><div class="section-kicker">ТОЛЬКО В ЭТОМ БРАУЗЕРЕ</div><h1>КОМПЛЕКТ СОБРАН.<br><em>СЦЕНАРИЙ ПРОЙДЕН.</em></h1><p>Демо-заказ ${esc(o.id)} ${storageOK?'сохранён в этом браузере':'создан только в памяти этой вкладки: хранилище недоступно'}.<br>Он не отправлен GTA, не передан в производство и не оплачен.</p><div class="success-box"><div class="summary-row"><span>Сумма товаров · демо</span><b>${money(o.total)}</b></div><div class="summary-row"><span>Доставка</span><b>не рассчитана</b></div><div class="summary-row"><span>Списано демобонусов</span><b>${o.spent}</b></div><div class="summary-row"><span>Демобонусы в ожидании</span><b>${o.earned}</b></div><p>В кабинете можно проверить точную версию демомакета, запросить правки и пройти условные этапы производства после согласования. Уведомления клиенту не отправляются.</p></div><div class="button-row"><a class="button dark" href="#/order/${esc(o.id)}">К демомакету и этапам ↗</a><a class="button secondary" href="#/catalog">Вернуться в магазин</a></div></div></section>`;}
function fiverox(){const progs=[['UNDERCOVER','Стойка в подарок','Проект: 1 рулон UNDERCOVER → бесплатная стойка GTA.','roll-stand','Комплектация стойки, период и ограничения программы требуют подтверждения.'],['ATOMGARD','NFC-модуль в подарок','Проект: 1 рулон ATOMGARD → NFC-модуль.','nfc-stand','Модуль не равнозначен полной NFC-стойке. Исполнение и совместимость уточняются.'],['DETRONA','Панно из 3 панелей','Проект: 1 рулон DETRONA → панно с DETRONA, студией и GTA.','modular-panel','Размеры, макет и порядок согласования брендинга требуют подтверждения.']];return `<section class="page dark-page">${bread('GTA × FIVEROX')}<div class="partner-hero"><div class="partner-hero-copy"><div class="section-kicker">ПАРТНЁРСКОЕ НАПРАВЛЕНИЕ</div><div class="partner-signatures"><img src="assets/logo.png" alt="GTA"><span>×</span><b>FIVEROX</b></div><h1>БОЛЬШЕ ВОЗМОЖНОСТЕЙ.<br><em>ОДИН ХАРАКТЕР.</em></h1><p>Плёночные решения FIVEROX и оснащение GTA в одном проекте студии. Здесь — проекты предложений для мастеров и детейлинг-команд.</p><div class="button-row"><a href="#/fiverox?section=programs" class="button">Изучить программы ↓</a><a class="text-link" href="#/catalog">Магазин GTA ↗</a></div><div class="form-note">GTA не продаёт плёнку. Планируемая роль GTA — сбор и передача заявок в FIVEROX. Сейчас это демонстрация: заявки не собираются и не отправляются; статус и условия сотрудничества не подтверждаются этой страницей.</div></div><div class="partner-photo"><img src="assets/studio.png" alt="Концепт оформления детейлинг-студии"><div class="photo-text">ПЛЁНКА. СТИЛЬ.<br><span>ТВОЁ ПРОСТРАНСТВО.</span></div></div></div><div class="partner-intro" id="programs"><h2>ВЫБЕРИ СВОЙ<br><em>СЦЕНАРИЙ.</em></h2><p>Подарки GTA могут стать частью будущих партнёрских предложений. Ниже — рабочие условия для обсуждения, не действующая акция. Они не связаны с демобонусами интернет-магазина.</p></div><div class="partner-programs">${progs.map(([brand,gift,desc,id,extra],i)=>`<article class="program"><div class="program-number">0${i+1}<span>ПРОЕКТ УСЛОВИЙ</span></div><h3>${brand}</h3><p>${desc}</p><div class="gift">${gift}</div><div class="program-art">${visual(P.find(p=>p.id===id))}</div><p class="program-detail">${extra}</p><button class="button secondary small" data-program="${brand}">Посмотреть демозаявку ↗</button></article>`).join('')}</div><div class="program-large"><div><div class="section-kicker">04 / БОЛЬШЕ МАСШТАБ</div><h3>3 рулона →<br>неон 40 × 90</h3><p>Предварительный вариант подарка. Бренд плёнки, единицы измерения, размеры, комплектация и ограничения ещё не подтверждены.</p><button class="button secondary small" data-program="Неон за 3 рулона">Открыть демосценарий ↗</button></div><div class="large-mark">40×90<br><span style="color:#51d8cb55">NEON</span></div></div><div class="program-large"><div><div class="section-kicker">05 / АВТОРИЗОВАННАЯ СТУДИЯ</div><h3>Полное оснащение.<br>Единый проект.</h3><p>Проект: авторизация по договору FIVEROX и полное оснащение за счёт FIVEROX. Перечень оборудования, критерии, финансирование и договор требуют отдельного подтверждения.</p><button class="button small" data-program="Авторизация FIVEROX">Пример заявки на авторизацию ↗</button></div><div style="padding:0;overflow:hidden"><img src="assets/art.png" alt="Концепт оснащения студии" style="height:100%;width:100%;object-fit:cover;max-height:320px"></div></div><div class="fiverox-steps"><div><b>01 / ВЫБОР</b><h3>Сначала — сценарий</h3><p>Выбираешь интересующую программу. Сейчас можно только проверить интерфейс.</p></div><div><b>02 / СОГЛАСОВАНИЕ</b><h3>Затем — конкретные условия</h3><p>После запуска предполагается передача заявки FIVEROX только с согласия клиента.</p></div><div><b>03 / ПРОЕКТ</b><h3>После — твоя студия</h3><p>Объём, макеты, сроки и обязательства фиксируются отдельно. Демо ничего не гарантирует.</p></div></div><section class="request-section" id="partner-request"><div><div class="section-kicker">ПРИМЕР ЗАЯВКИ / БЕЗ ОТПРАВКИ</div><h2>С ЧЕГО НАЧНЁМ<br><em>ТВОЙ ПРОЕКТ?</em></h2><p>Посмотри, как будет устроен первый контакт. Для демонстрации используются только фиксированные вымышленные данные.</p><p>В рабочей версии здесь потребуются подтверждённые контакты получателя заявки и согласие на передачу данных. Сейчас ничего не передаётся GTA или FIVEROX.</p></div><form id="partner-form" novalidate><div class="field-grid"><label class="field">Студия · пример<input value="Демо-студия 01" readonly></label><label class="field">Масштаб · пример<select name="scale"><option>Одна студия</option><option>Сеть студий</option><option>Новая студия</option></select></label></div><label class="field" style="margin-top:18px">Программа<select id="partner-program" name="program"><option value="">Выбери программу</option>UNDERCOVER</option><option>ATOMGARD</option><option>DETRONA</option><option>Неон за 3 рулона</option><option>Авторизация FIVEROX</option></select></label><label class="check-label"><input id="partner-confirm" type="checkbox"><span>Понимаю, что условия предварительные. Проверяю только интерфейс; заявка не будет отправлена.</span></label><button class="button dark" type="submit">Проверить демозаявку ↗</button><p id="partner-result" class="error-note" role="status" hidden></p></form></section><section class="faq"><h2>КОРОТКО О ВАЖНОМ.</h2><div class="detail-accordion"><details><summary>Можно купить плёнку на сайте GTA?</summary><p>Нет. В магазине GTA — собственные изделия, оснащение и декор. Плёночное направление относится к FIVEROX; действующие продажи и условия здесь не представлены.</p></details><details><summary>Эти подарки уже доступны?</summary><p>Нет, на этой странице показан проект условий. Сроки, участие, доступность, комплектация, подтверждение покупки и выдача подарков пока не утверждены.</p></details><details><summary>Отправится ли эта заявка?</summary><p>Нет. Кнопка показывает локальный результат проверки формы. Здесь нет сервера, отправки сообщений, CRM или сбора контактов.</p></details></div></section></section>`;}
function accountMenu(tab){const entries=[['','Мой гараж'],['orders','Демо-заказы'],['bonus','Бонусная карта'],['referrals','Пригласи студию'],['creator','Кабинет автора'],['favorites','Избранное']];return `<aside class="account-nav"><div class="account-avatar">D</div><div class="identity"><strong>Демо-мастер</strong><small>ДЕМО-СТУДИЯ 01 / ЛОКАЛЬНО</small></div>${entries.map(([id,title])=>`<a href="#/account${id?'/'+id:''}" class="${tab===id?'active':''}">${title}<span>↗</span></a>`).join('')}<button class="link-button" data-action="logout">Выйти из деморежима</button></aside>`;}
function loginPage(next){return `<section class="page">${bread('Личный кабинет')}<div class="login-shell"><div class="login-art"><img src="assets/crew.png" alt="Маскоты GTA, мастера детейлинга"></div><div class="login-copy"><div class="section-kicker">GARAGE CREW / ПРИМЕР ЛИЧНОГО КАБИНЕТА</div><h1>ТВОЯ СТУДИЯ.<br>ТВОЙ <em>ГАРАЖ.</em></h1><p>Все свои детали в одном месте. Посмотри, как могут выглядеть заказы, бонусная карта и реферальная программа.</p><ul><li>История локальных демо-заказов</li><li>Пример бонусного баланса и начислений</li><li>Пример приглашения другой студии</li></ul><button class="button dark" data-login="${esc(next||'account')}">Открыть демо-кабинет ↗</button><p class="fineprint">Это не регистрация и не вход в настоящий аккаунт. Пароль, телефон и email не требуются. Используется вымышленный профиль; данные хранятся только в этом браузере.</p>${state.orders.length?'<a href="#/account/orders?guest=1" class="text-link">Посмотреть локальную историю без входа ↗</a>':''}</div></div></section>`;}
function bonusCard(){return `<div class="bonus-card"><img src="assets/logo.png" alt="GTA"><div class="card-type">GARAGE CREW</div><div class="card-number">0000 &nbsp; 0000 &nbsp; DEMO</div><div class="card-bottom"><span>ДЕМО-МАСТЕР / ОБРАЗЕЦ КАРТЫ</span><span>НЕ ПЛАТЁЖНАЯ КАРТА</span></div></div>`;}
function draftRules(){return `<div class="draft-rules"><b>Предварительная программа · условия согласуются</b>Демоусловия для согласования, не действующая акция. 1 демобалл = 1 ₽ только в симуляции. Списание до 20% стоимости товаров и не выше доступного баланса. Начисление: 5 баллов за каждые полные 100 ₽ товаров после списания; доставка не участвует. Баллы не деньги и не дают реальной скидки.</div>`;}
function orderCard(o){return `<article class="order-card"><div class="order-head"><div><strong>${esc(o.id)}</strong><small>${esc(new Date(o.date).toLocaleDateString('ru-RU'))} / ЛОКАЛЬНЫЙ ПРИМЕР</small></div><span class="order-status ${o.done&&!o.refunded?'done':''}">${ORDER_STATUS[M.normalizeOrder(o).lifecycle.status]}</span></div><ul class="order-lines">${o.items.map(x=>`<li><span>${esc(x.name)} · ${esc(x.variant)} / ${esc(x.color)} × ${M.integer(x.qty,1,99)}</span><b>${money(Number(x.unit)*M.integer(x.qty,1,99))}</b></li>`).join('')}</ul><p>${o.delivery==='delivery'?'Доставка':'Самовывоз'} · только сценарий, стоимость не рассчитана.<br>${o.refunded?'Демо-возврат: бонусный расчёт скорректирован.':`Демобонусы: списано ${o.spent}; ${o.done?'начислено':'в ожидании'} ${o.earned}.`} Реальной оплаты и отправки нет.</p><div class="order-foot"><b>${money(o.total)}<small>Пример суммы товаров</small></b><a href="#/order/${esc(o.id)}" class="button small dark">Макет и этапы ↗</a><button class="button small secondary" data-reorder="${esc(o.id)}">Повторить состав ↗</button></div></article>`;}
function accountPage(tab='',guest=false){if(!state.member&&!guest)return loginPage(`account${tab?'/'+tab:''}`);let content='';
if(tab==='orders')content=`<h1>ДЕМО-ЗАКАЗЫ.</h1><p class="lede">Локальная история в этом браузере. Эти заказы не существуют у продавца.</p>${state.orders.length?state.orders.map(orderCard).join(''):'<div class="account-empty">Пока нет демо-заказов. Собери комплект и пройди оформление.<br><a class="button small dark" style="margin-top:15px" href="#/catalog">В магазин ↗</a></div>'}`;
else if(tab==='bonus')content=`<h1>ТВОЯ БОНУСНАЯ КАРТА.</h1><p class="lede">Для своих. В своём стиле. Пока — в демонстрационном режиме.</p><div class="loyalty-grid">${bonusCard()}<div class="bonus-balance"><div class="section-kicker">ДОСТУПНО В СИМУЛЯЦИИ</div><strong>${state.points.toLocaleString('ru-RU')}</strong><p>демобаллов · ${state.pending} в ожидании${state.bonusDebt?'<br>Демо-коррекция после возвратов: '+state.bonusDebt+' баллов':''}<br>Стартовый баланс ${M.RULES.seed} баллов вымышленный.</p><a href="#/catalog" class="button dark small">Проверить в корзине ↗</a></div></div>${draftRules()}<div class="rule-grid"><div><strong>5 / 100</strong><h3>Пример начисления</h3><p>За каждые полные 100 ₽ товаров после списания. Активация — после имитации завершения заказа.</p></div><div><strong>до 20%</strong><h3>Пример списания</h3><p>Только на товары в демокорзине. Нельзя потратить больше доступного баланса.</p></div><div><strong>1 : 1</strong><h3>Пример эквивалента</h3><p>Один балл уменьшает демосумму на один рубль. Это не обещание скидки.</p></div></div><div class="account-section-heading"><h2>История демобаллов</h2></div>${state.ledger.map(l=>`<div class="ledger-row"><div>${esc(l.label)}<small>${esc(l.note||'Только демонстрационный баланс')}</small></div><b>${l.amount>0?'+':''}${l.amount}</b></div>`).join('')}<div class="ledger-row"><div>Стартовый пример баланса<small>Вымышленное значение для тестирования</small></div><b>+${M.RULES.seed}</b></div>`;
else if(tab==='referrals'){const ref=referralLink();content=`<h1>СВОИ РЕКОМЕНДУЮТ СВОИМ.</h1><p class="lede">Предварительная реферальная программа · не действующая акция.</p><div class="referral-hero"><div><div class="section-kicker">GARAGE CREW / ПРИГЛАСИ СТУДИЮ</div><h2>ХОРОШИЙ СТИЛЬ<br>СТОИТ <em style="color:#fff7ec">ПЕРЕДАТЬ.</em></h2><p>Пример механики: +300 демобаллов после первого завершённого заказа приглашённой студии от 3 000 ₽ за товары после скидок.</p></div><div class="referral-symbol">↗↗</div></div><label class="option-label" for="referral-link">Твоя демоссылка · без отслеживания</label><div class="copy-link"><input id="referral-link" readonly value="${esc(ref)}"><button class="button dark" data-action="copy-referral">Скопировать ↗</button></div><div class="copy-note" id="copy-status" role="status">Ссылка открывает этот демокаталог. Переходы и приглашённые не отслеживаются. Ссылка используется в демонстрационном сценарии приглашения.</div><div class="stats-grid"><div class="stat"><span>Реальных приглашений</span><strong>0</strong><small>Отслеживание не подключено</small></div><div class="stat"><span>Демосценариев завершено</span><strong>${state.referralDone?1:0}</strong><small>Только в этом браузере</small></div><div class="stat"><span>Демобаллов за приглашение</span><strong>${state.referralDone?300:0}</strong><small>Не реальные награды</small></div></div><div class="referral-demo"><div><strong>Проверить начисление на вымышленном примере</strong><p>Имитируем первого друга и его завершённый заказ на 3 000 ₽ товаров после скидок. Один тест на локальный профиль. Никаких реальных приглашений.</p></div><button class="button small secondary" data-action="simulate-referral" ${state.referralDone?'disabled':''}>${state.referralDone?'Сценарий проверен':'Имитировать +300'}</button></div>${draftRules()}<div class="detail-accordion"><details><summary>Что нужно согласовать перед запуском?</summary><p>Кто может участвовать, порог заказа, размер и срок действия наград, возвраты и отмены, запрет самоприглашения, учёт первого заказа и согласия на обработку данных. До утверждения условий программа не действует.</p></details></div>`;}
else if(tab==='creator')content=creatorAccount();
else if(tab==='favorites')content=`<h1>ТВОИ НАХОДКИ.</h1><p class="lede">Сохранённые концепты. Избранное хранится только в этом браузере.</p><div class="product-grid">${productsGrid(P.filter(p=>state.favorites.includes(p.id)))}</div>`;
else content=`<h1>ПРИВЕТ, ДЕМО-МАСТЕР.</h1><p class="lede">Твой локальный гараж. Никаких паролей, платежей и настоящих заказов.</p><div class="account-welcome"><div><div class="section-kicker">GTA / GARAGE CREW</div><h2>ДЕТАЛИ СОБИРАЮТСЯ<br>В <em>ХАРАКТЕР.</em></h2><p>Продолжай собирать пространство, в котором приятно работать.</p><a href="#/catalog" class="button small">Найти свой предмет ↗</a></div><img src="assets/crew.png" alt="Маскоты GTA"></div><div class="stats-grid"><a href="#/account/bonus" class="stat"><span>Доступно демобаллов ↗</span><strong>${state.points.toLocaleString('ru-RU')}</strong><small>${state.pending} в ожидании · вымышленные баллы</small></a><a href="#/account/orders" class="stat"><span>Локальных демо-заказов ↗</span><strong>${state.orders.length.toString().padStart(2,'0')}</strong><small>Не отправлены продавцу</small></a><a href="#/account/favorites" class="stat"><span>В твоём избранном ↗</span><strong>${state.favorites.length.toString().padStart(2,'0')}</strong><small>Сохранено в этом браузере</small></a></div><div class="account-section-heading"><h2>Последний демо-заказ</h2><a href="#/account/orders">Вся история ↗</a></div>${state.orders.length?orderCard(state.orders[0]):'<div class="account-empty">Твой первый комплект ещё впереди. В демокаталоге можно выбрать изделия, настроить исполнение и проверить оформление.</div>'}<div class="account-section-heading"><h2>Друзья твоей студии</h2><a href="#/account/referrals">Пример реферальной программы ↗</a></div><div class="draft-rules"><b>Проверяй интерфейс без настоящих данных</b>Баланс, профиль и заказы в этой версии только демонстрационные. Выход закрывает кабинет, но не удаляет корзину и историю.</div><button class="link-button storage-reset" data-action="reset-demo">Удалить локальные демоданные и начать заново</button>`;
return `<section class="page">${bread('Личный кабинет · демо')}<div class="account-layout">${state.member?accountMenu(tab):'<aside class="account-nav"><a href="#/account">Открыть демо-кабинет ↗</a><p class="fineprint">Гостевая локальная история. Реальная авторизация не подключена.</p></aside>'}<div class="account-content">${content}</div></div></section>`;}
function collaborationPage(){return `<section class="page creator-page">${bread('Коллаборации / GTA CREW')}<div class="creator-hero"><div><div class="section-kicker">GTA CREW / АВТОРЫ · МАСТЕРА · СТУДИИ</div><h1>ПОКАЖИ ХАРАКТЕР.<br>ДАЙ СВОИМ<br><em>БОЛЬШЕ.</em></h1><p>Твой честный обзор. Предмет с характером GTA. Специальные условия для твоей аудитории и вознаграждение за покупки.</p><div class="button-row"><a href="#/collaborations?section=calculator" class="button dark">Посчитать сценарий ↗</a><a href="#/collaborations?section=creator-request" class="text-link">Пример участия ↓</a></div><div class="creator-disclaimer">Проект программы. Механика: 20% автору за первую покупку, 10% за каждую следующую покупку того же клиента без срока окончания привязки. База расчёта, срок скидки покупателю, договор и правила ещё утверждаются. Реальных продаж, заявок и выплат в демо нет.</div></div><div class="creator-art"><div class="creator-orbit">CREW<br><span>20 / 10</span></div><img src="assets/crew.png" alt="Маскоты GTA: команда мастеров"><div class="creator-sticker">ЧЕСТНЫЙ<br>ОБЗОР.<br><span>СВОЙ ГОЛОС.</span></div></div></div><div class="creator-offer-grid"><article><span>01 / ДЛЯ ТЕБЯ</span><h2>ПРЕДМЕТ<br>ДЛЯ ОБЗОРА.</h2><p>Предложение GTA: любой согласованный материал, мерч или товар из доступного ассортимента для честного обзора. Бесплатный комплект и его бюджет утверждаются индивидуально.</p><small>Это не обещание неограниченной бесплатной продукции.</small></article><article><span>02 / ДЛЯ ТВОИХ</span><h2>−20%<br>ПО ТВОЕЙ ССЫЛКЕ.</h2><p>Предложение: покупатель получает 20% скидки. До запуска нужно определить, действует ли скидка только на первую или на все покупки, товары-участники и порядок применения.</p><small>Демоссылка не активирует настоящую скидку.</small></article><article><span>03 / ЗА РЕЗУЛЬТАТ</span><h2>20% + 10%<br>ДЛЯ АВТОРА.</h2><p>За первую покупку клиента — 20%, за каждую следующую — 10% пожизненно, без повторного перехода по ссылке. Предложенная база: оплаченные товары после скидки. Это комиссионный доход, не чистая прибыль.</p><small>База и момент выплаты требуют отдельного согласования.</small></article></div><section class="creator-calculator" id="calculator"><div class="section-title-row"><div><div class="section-kicker">ПРОВЕРЬ ЭКОНОМИКУ / БЕЗ ОБЕЩАНИЙ</div><h2>ТВОЯ АУДИТОРИЯ.<br>ТВОЙ <em>СЦЕНАРИЙ.</em></h2></div><span class="badge">Не прогноз дохода</span></div><p class="calculator-note">25% — заданный сценарий конверсии, а не ожидаемый результат. Подписчики не равны охвату или покупателям; аудитории разных каналов могут пересекаться.</p><div class="calculator-layout"><form id="creator-calculator-form"><div class="calculator-mode" role="group" aria-label="Модель расчёта"><button type="button" data-calc-mode="simple" class="selected" aria-pressed="true">Простой сценарий</button><button type="button" data-calc-mode="funnel" aria-pressed="false">Подробная воронка</button></div><div class="field-grid"><label class="field">Подписчики<input type="number" name="followers" id="calc-followers" value="10000" min="0" max="1000000" step="1" inputmode="numeric"></label><label class="field">Средний чек, ₽<input type="number" name="average" id="calc-average" value="5000" min="0" max="100000" step="0.01" inputmode="decimal"></label></div><label class="field" style="margin-top:16px">Что означает средний чек<select id="calc-base" name="base"><option value="listed">Цена товаров ДО скидки 20%</option><option value="paid">УЖЕ ОПЛАЧЕННЫЕ товары после скидки</option></select></label><div id="simple-inputs"><label class="field" style="margin-top:16px">Доля всех подписчиков, совершивших покупку, %<input type="number" id="calc-conversion" value="25" min="0" max="100" step="0.1" inputmode="decimal"></label><p class="copy-note">Прямая модель: подписчики × конверсия. Значение 25% не обосновано статистикой продаж.</p></div><div id="funnel-inputs" hidden><div class="field-grid" style="margin-top:16px"><label class="field">Охват от подписчиков, %<input id="calc-reach" type="number" value="40" min="0" max="100" step="0.1"></label><label class="field">Переходы от охвата, %<input id="calc-click" type="number" value="5" min="0" max="100" step="0.1"></label></div><label class="field" style="margin-top:16px">Покупки от переходов, %<input id="calc-purchase" type="number" value="3" min="0" max="100" step="0.1"></label><p class="copy-note">40%, 5% и 3% — редактируемые вымышленные значения, не отраслевые нормы.</p></div><div class="field-grid" style="margin-top:16px"><label class="field">Повторных заказов на клиента за период<input id="calc-repeats" type="number" value="2" min="0" max="100" step="1"></label><label class="field">Период сценария, месяцев<input id="calc-period" type="number" value="12" min="1" max="120" step="1"></label></div><label class="field" style="margin-top:16px">Срок скидки 20% · пока не утверждён<select id="calc-discount"><option value="first">Сценарий: только первая покупка</option><option value="always">Сценарий: все покупки клиента</option></select></label><p class="copy-note">Пожизненная привязка не означает бесконечный доход. Число повторов задаётся за выбранный период, не в год. Смена только периода не меняет сумму расчёта. Здесь предполагается, что каждый привлечённый покупатель сделал указанное число повторов.</p><p class="copy-note">Диапазоны: 0–1 000 000 подписчиков; 0–100 000 ₽; 0–100%. Повторов: 0–100; период: 1–120 месяцев. Выходящие за диапазон значения ограничиваются в расчёте. Количество людей округляется вниз на каждом шаге. Суммы рассчитываются до копеек.</p></form><div class="calculator-results" id="calculator-results" aria-live="polite"></div></div><div class="calculator-caveat"><b>Что расчёт не учитывает</b>Себестоимость бесплатного комплекта и проданных товаров, производство контента, доставку, эквайринг, возвраты, налоги и иные расходы. Остаток GTA до этих затрат — не прибыль. Выплаты автору здесь не производятся.</div></section><section class="creator-rules"><div class="section-title-row"><h2>ЧЕСТНО.<br><em>ПО ДОГОВОРЁННОСТИ.</em></h2><span class="badge">Предложения для согласования</span></div><div class="creator-rule-grid"><div><b>01 / ЧЕСТНОСТЬ</b><h3>Твой опыт, твой голос.</h3><p>Обзор не обязан быть положительным. Проверка фактических данных и требований к публикации не должна превращаться в цензуру мнения.</p></div><div><b>02 / КАНАЛЫ</b><h3>Везде, где договорились.</h3><p>Публикации — в согласованном списке каналов, где размещение разрешено законом и правилами площадки. Совместный постинг возможен, если платформа его поддерживает. Форматы и сроки согласуются отдельно.</p></div><div><b>03 / РЕЗУЛЬТАТ</b><h3>Сначала выполненный заказ.</h3><p>Предлагаемый порядок: покупка оплачена, выполнена и не возвращена; затем вознаграждение становится доступно. Срок ожидания и выплаты ещё нужно установить.</p></div><div><b>04 / ПРАВИЛА</b><h3>Без накруток и двойного счёта.</h3><p>Предлагаем исключить самоприглашения и не суммировать 20% с демобонусами и другими реферальными наградами. Предлагаем закреплять первого допустимого автора за клиентом без смены от новой ссылки. Для пожизненной привязки нужна запись клиент → автор на сервере; cookie или это локальное демо её не заменяют.</p></div></div><div class="draft-rules"><b>Перед первой публикацией нужен согласованный бриф и правовая проверка</b>Нужно определить участников, комплект и доставку, каналы и сроки публикаций, маркировку и раскрытие предоставленного продукта, расчёты, налоги и ограничения площадок. Повторное использование фото и видео на сайте GTA или в рекламе — только по отдельному согласованию. Эта страница не является договором или юридической консультацией.</div></section><section class="creator-request" id="creator-request"><div><div class="section-kicker">КОЛЛАБОРАЦИИ / ПРИМЕР ЗАЯВКИ</div><h2>ЕСТЬ СВОЯ<br><em>АУДИТОРИЯ?</em></h2><p>Посмотри демосценарий первого знакомства. Реальные имя, ссылки на аккаунты, контакты и адрес не запрашиваются.</p><p>После запуска сотрудничество возможно только после отдельного согласования условий. Никаких автоматических обещаний подарков или заработка.</p></div><form id="creator-form" novalidate><label class="field">Профиль · вымышленный пример<input value="Демо-автор / Детейлинг-канал" readonly></label><div class="field-grid" style="margin-top:17px"><label class="field">Интересующая категория<select id="creator-category"><option value="">Выбери направление</option><option>Оснащение студии</option><option>Автоарт и декор</option><option>Мерч · доступность уточняется</option><option>NFC / QR и приёмка</option><option>Свет и навигация</option></select></label><label class="field">Формат примера<select><option>Обзор в своих каналах</option><option>Серия публикаций</option><option>Индивидуальная коллаборация</option></select></label></div><label class="check-label"><input id="creator-confirm" type="checkbox"><span>Понимаю, что это проект условий и демозаявка. Информация никуда не отправляется; сотрудничество не оформляется.</span></label><button class="button dark" type="submit">Проверить демозаявку ↗</button><p id="creator-result" class="error-note" role="status" hidden></p></form></section></section>`;}
let calculatorMode='simple';
function updateCalculator(){if(!$('#calculator-results'))return;const result=M.ambassador({followers:$('#calc-followers').value,average:$('#calc-average').value,base:$('#calc-base').value,conversion:$('#calc-conversion').value,reach:$('#calc-reach').value,click:$('#calc-click').value,purchase:$('#calc-purchase').value,mode:calculatorMode,repeats:$('#calc-repeats').value,period:$('#calc-period').value,discount:$('#calc-discount').value});$('#calculator-results').innerHTML=`<div class="section-kicker">ВЫМЫШЛЕННЫЙ РАСЧЁТ / ПЕРВЫЕ 20% · ПОВТОРНЫЕ 10%</div><div class="calc-main"><span>Вознаграждение автора за ${result.period} мес. сценария</span><strong>${money(result.reward)}</strong><small>Комиссионный доход до расходов и налогов. Не гарантия.</small></div><div class="calc-funnel"><span>${result.followers.toLocaleString('ru-RU')} подписчиков</span>${calculatorMode==='funnel'?`<b>→</b><span>${result.reached.toLocaleString('ru-RU')} охват</span><b>→</b><span>${result.clicked.toLocaleString('ru-RU')} переходов</span>`:''}<b>→</b><span>${result.buyers.toLocaleString('ru-RU')} покупок</span></div><div class="summary-row"><span>За ${result.buyers.toLocaleString('ru-RU')} первых заказов · 20%</span><b>${money(result.rewardFirst)}</b></div><div class="summary-row"><span>За ${result.repeatOrders.toLocaleString('ru-RU')} повторных заказов · 10%</span><b>${money(result.rewardRepeat)}</b></div><div class="summary-row"><span>Оплачено покупателями за товары</span><b>${money(result.revenue)}</b></div><div class="summary-row"><span>Остаток GTA до затрат</span><b>${money(result.store)}</b></div><div class="calc-example"><b>Первая покупка в этой модели</b><div><span>До скидки</span><strong>${money(result.list)}</strong></div><div><span>Покупатель платит</span><strong>${money(result.paid)}</strong></div><div><span>Автору · 20% от оплаты</span><strong>${money(result.commission)}</strong></div><div><span>GTA до себестоимости и расходов</span><strong>${money(result.residual)}</strong></div></div><div class="calc-example"><b>Каждая повторная покупка того же клиента</b><div><span>Покупатель платит</span><strong>${money(result.repeatPaid)}</strong></div><div><span>Автору · 10% от оплаты</span><strong>${money(result.repeatCommission)}</strong></div><div><span>Покупок за ${result.period} мес.</span><strong>${result.repeatOrders.toLocaleString('ru-RU')}</strong></div></div><p class="fineprint">Предложенная база расчёта и срок скидки ещё не утверждены. Доставка исключена. Количество покупателей — условная целая модель; реальный результат может быть нулевым.</p>`;}

function creatorAccount(){const co=state.creator,valid=co.orders.filter(o=>!o.refunded),first=valid.filter(o=>o.type==='first').reduce((s,o)=>s+o.reward,0),repeat=valid.filter(o=>o.type==='repeat').reduce((s,o)=>s+o.reward,0),refund=co.orders.filter(o=>o.refunded).reduce((s,o)=>s+o.reward,0);return `<h1>КАБИНЕТ АВТОРА.</h1><p class="lede">Отдельный пример денежных комиссий. Это не бонусы покупателя и не реальные выплаты.</p><div class="creator-account-banner"><div class="section-kicker">ПЕРВЫЙ ЗАКАЗ / КАЖДЫЙ ПОВТОРНЫЙ</div><h2>20% СЕЙЧАС.<br>10% С КАЖДОГО ПОВТОРА.</h2><p>Тот же клиент остаётся за автором без ограничения срока. В рабочей системе привязка хранится на сервере и не требует повторного клика по ссылке.</p><a class="text-link" href="#/collaborations?section=calculator">Посчитать свой сценарий ↗</a></div><div class="stats-grid"><div class="stat"><span>Первые покупки · демокомиссия</span><strong>${money(first)}</strong><small>20% оплаченных товаров</small></div><div class="stat"><span>Повторные покупки · демокомиссия</span><strong>${money(repeat)}</strong><small>10% оплаченных товаров</small></div><div class="stat"><span>Сторнировано за возвраты</span><strong>${money(refund)}</strong><small>Реальных выплат нет</small></div></div><div class="draft-rules"><b>Один вымышленный клиент / одна локальная модель</b>${co.customer?'ДЕМО-КЛИЕНТ-01 закреплён за ДЕМО-АВТОРОМ.':'Имитируй первую выполненную покупку, чтобы появился ДЕМО-КЛИЕНТ-01.'} Никакого реального клиента или пожизненного серверного учёта здесь нет. Удаление данных браузера сбросит этот пример.</div><div class="creator-simulator"><div><h3>Пройти цикл заказа и возврата</h3><p>Пример цены до скидки: 5 000 ₽. Первый заказ: 4 000 ₽ оплачено, 800 ₽ автору. Повтор: 500 ₽ автору без повторной скидки или 400 ₽ с ней. Срок скидки ещё согласуется.</p><label class="field">Скидка на повтор · сценарий<select id="creator-repeat-policy"><option value="first" ${co.policy!=='always'?'selected':''}>Только на первый заказ</option><option value="always" ${co.policy==='always'?'selected':''}>На все покупки</option></select></label></div><div class="button-row"><button class="button dark small" data-action="creator-first" ${co.customer?'disabled':''}>Имитировать первый заказ</button><button class="button secondary small" data-action="creator-repeat" ${!co.customer?'disabled':''}>Имитировать повторный</button></div></div><div class="account-section-heading"><h2>Демокомиссии и возвраты</h2></div>${co.orders.length?co.orders.map(o=>`<article class="creator-order"><div><strong>${o.type==='first'?'Первый заказ · 20%':'Повторный заказ · 10%'}</strong><small>ДЕМО-КЛИЕНТ-01 · ${esc(o.id)}<br>${money(o.paid)} товаров после скидок · выполнен в симуляции</small></div><b class="${o.refunded?'refunded':''}">${o.refunded?'Сторно ':''}${money(o.reward)}</b>${o.refunded?'<span class="order-status">Демо-возврат</span>':`<button class="link-button" data-creator-refund="${esc(o.id)}">Имитировать возврат</button>`}</article>`).join(''):'<div class="account-empty">Пока нет демокомиссий. Кнопки выше не создают реальных заказов или обязательств.</div>'}<p class="page-end-note">Здесь показываются только выполненные заказы вымышленного клиента. В рабочей версии нужны статусы ожидания оплаты, выполнения, возвратов и доступности выплат. Сроки выплат, база и договор ещё не утверждены. Кнопки получения денег нет.</p>`;}
const KIT_GROUPS=[['stand','Стойка и порядок',['roll-stand','wall-roll-stand','squeegee-organizer','brush-holder','towel-holder']],['light','Свет и навигация',['neon-sign','zone-sign','bay-number']],['art','Автоарт и характер',['aluminium-poster','modular-panel','brand-poster']],['reception','Приёмка и контакт',['nfc-stand','wall-qr','key-tray','business-card-holder','care-cards']]];let kitState={};
function kitPage(){return `<section class="page">${bread('Конструктор комплекта')}<div class="page-head"><div><div class="section-kicker">GTA / СОБЕРИ СВОЙ ДЕТЕЙЛИНГ</div><h1>ТВОЁ ПРОСТРАНСТВО.<br><em>ТВОЙ КОМПЛЕКТ.</em></h1><p>Выбери по одному акценту для каждой зоны. Без обязательных позиций и выдуманных комплектных скидок.</p></div>${tag('Конструктор · демо')}</div><div class="kit-layout"><div class="kit-controls">${KIT_GROUPS.map(([id,name,ids],i)=>`<label class="kit-control"><span>0${i+1} / ${name}</span><select data-kit="${id}" aria-label="${name}"><option value="">Пока без этой позиции</option>${ids.map(pid=>{const p=P.find(p=>p.id===pid);return `<option value="${p.id}" ${kitState[id]===pid?'selected':''}>${p.name} · ${money(p.price)}</option>`}).join('')}</select></label>`).join('')}<div class="form-note">В комплект добавляется базовое исполнение, первый цвет, 1 шт. каждого предмета. Другие варианты можно выбрать в карточке товара. Все суммы — демоцены.</div><a class="text-link" href="#/catalog">Посмотреть весь каталог ↗</a></div><div><div class="kit-preview" id="kit-preview"></div><div class="kit-total"><div><span>Сумма выбранных предметов · демо</span><strong id="kit-total">0 ₽</strong></div><button class="button" data-action="add-kit" id="kit-add">Добавить комплект в корзину ↗</button></div><p class="copy-note">Это состав комплекта, а не визуализация реальной расстановки. Размеры, сочетаемость и итоговый дизайн нужно согласовать.</p></div></div><section class="future-mechanics"><div class="section-kicker">ЕЩЁ БОЛЬШЕ ВОЗМОЖНОСТЕЙ / ПРОЕКТ МЕХАНИК</div><h2>ИДЕИ ДЛЯ <em>СЛЕДУЮЩЕГО УРОВНЯ.</em></h2><div class="creator-rule-grid"><div><b>01 / КЛУБ ТЕСТЕРОВ</b><h3>Опыт важнее оценки.</h3><p>Предложение: образцы и награды за полезные фото, видео и обратную связь независимо от положительности мнения. Критерии и бюджет утверждаются.</p></div><div><b>02 / КОЛЛЕКЦИИ АВТОРОВ</b><h3>Твой взгляд на GTA.</h3><p>Совместные серии с авторами и студиями: макет, тираж, права и распределение доходов по отдельному соглашению.</p></div><div><b>03 / ПРЕДЗАКАЗ КОЛЛЕКЦИИ</b><h3>Сначала интерес.</h3><p>Проект будущей механики: тест спроса до производства. Сейчас нет сбора денег, резерва, очереди или обещаний выпуска.</p></div><div><b>04 / КОМАНДНЫЙ ЗАКАЗ</b><h3>Один стиль для всей сети.</h3><p>Персонализация нескольких студий и повтор макетов по согласованным исходникам. Загрузки файлов, скидки и автоматические заказы не подключены.</p></div></div></section></section>`;}
function updateKit(){if(!$('#kit-preview'))return;let amount=0,count=0;$('#kit-preview').innerHTML=KIT_GROUPS.map(([id,name])=>{const p=P.find(p=>p.id===kitState[id]);if(p){amount+=p.price;count++;return `<div class="kit-slot filled">${visual(p)}<div><span>${name}</span><b>${p.name}</b><small>${money(p.price)} · демо</small></div></div>`;}return `<div class="kit-slot"><span class="kit-plus">+</span><b>${name}</b><small>Добавь предмет слева</small></div>`;}).join('');$('#kit-total').textContent=money(amount);$('#kit-add').disabled=count===0;}

function homePage(){return `<section class="compact-hero"><div class="compact-background"></div><div class="compact-hero-copy"><div class="section-kicker">GTA / GARAGE TOOLS & ART</div><h1>ПРОКАЧАЙ<br>СВОЙ<br><em>ДЕТЕЙЛИНГ.</em></h1><p>Стойки, свет и автоарт для студии с характером.<br><span>Выбирай предметы. Собирай пространство.</span></p><div class="button-row"><a href="#/catalog" class="button">В магазин ↗</a><a href="#/kit" class="button secondary">Собрать комплект</a></div><div class="hero-bottom-note"><span>ПОД ТВОЙ ЛОГОТИП / ПОД ТВОЮ СТУДИЮ</span><a href="#/showcase">Полная вау-презентация ↗</a></div></div><div class="compact-layer compact-layer-back"><img src="assets/art.png" alt="Концепт оформления студии"></div><img class="compact-crew" src="assets/crew.png" alt="Маскоты GTA: команда мастеров детейлинга"><div class="compact-sticker"><span>TOOLS.<br>ART.<br>ATTITUDE.</span><b>GTA</b></div><a class="compact-scroll" href="#/catalog">Выбрать предмет ↓</a></section><section class="home-fast"><div class="category-strip">${C.filter(([id])=>id!=='all').map(([id,name])=>`<a href="#/catalog?category=${id}">${name}<span>↗</span></a>`).join('')}</div><div class="section-title-row"><div><div class="section-kicker">НАЧНИ С ОДНОЙ ДЕТАЛИ</div><h2>РАБОТАЕТ.<br>И <em>ВЫГЛЯДИТ.</em></h2></div><a class="text-link" href="#/catalog">Все ${P.length} концептов ↗</a></div><div class="product-grid">${P.slice(0,4).map(productCard).join('')}</div><div class="journey-strip"><div><b>01</b><span>Выбери предмет<br><small>Исполнение, цвет, количество</small></span></div><div><b>02</b><span>Согласуй макет<br><small>Точная версия перед запуском</small></span></div><div><b>03</b><span>Следи за этапами<br><small>Сейчас — локальный демосценарий</small></span></div><a href="#/how-it-works">Как это устроено ↗</a></div><div class="home-partner"><div><div class="section-kicker">СОБРАНО ПОД ТЕБЯ</div><h2>СТУДИЯ,<br>КОТОРУЮ <em>ПОМНЯТ.</em></h2><p>От стойки до светового акцента. Конструктор поможет собрать основу, а персонализация начинается с согласованного макета.</p><a href="#/kit" class="button dark">Собрать свой комплект ↗</a></div><div class="partner-wordmark">YOUR<br><span>GARAGE.</span><small>TOOLS / ART / ATTITUDE</small></div></div></section>`;}
function howItWorks(){return `<section class="page">${bread('Как заказать')}<div class="page-head"><div><div class="section-kicker">ОТ ИДЕИ ДО ТВОЕГО ПРОСТРАНСТВА</div><h1>СНАЧАЛА МАКЕТ.<br>ПОТОМ <em>ХАРАКТЕР.</em></h1><p>Так может быть устроен заказ индивидуального изделия. Это проект процесса: реальные сроки, стоимость разработки и число правок ещё нужно согласовать.</p></div>${tag('Демонстрация процесса')}</div><div class="process-grid"><article><span>01</span><h2>Выбор и состав</h2><p>Выбираешь концепт, исполнение и количество. В корзине проверяешь детали и отдельные сценарии цены. Все суммы пока демонстрационные.</p><a href="#/catalog" class="text-link">Открыть каталог ↗</a></article><article><span>02</span><h2>Точная версия макета</h2><p>В локальном заказе появляется условный макет V1. Можно оставить тестовый комментарий, запросить правки или согласовать именно эту версию. Новая версия требует нового согласования.</p></article><article><span>03</span><h2>После согласования</h2><p>Только после согласования актуальной версии демосценарий разрешает перейти к производству. Сам сайт не отправляет файл на станок и не запускает физическую работу.</p></article><article><span>04</span><h2>Понятные этапы</h2><p>Производство → проверка → готовность → завершение. В этой версии этапы переключаются вручную в отдельном пульте демонстрации и не являются настоящими статусами заказа.</p></article></div><div class="info-grid"><div><h2>Что подготовить для стойки?</h2><p>Количество рулонов, их ширину, диаметр и массу, доступное место и пожелания к размещению. Совместимость и допустимые нагрузки нужно подтвердить для выбранной конструкции. Плёнка в поставку не входит.</p></div><div><h2>Что подготовить для автоарта?</h2><p>Формат, число панелей, размеры стены и пожелания к сюжету. Права на логотипы и изображения, материал, крепления и итоговый макет согласуются отдельно.</p></div><div><h2>Что подготовить для света?</h2><p>Место установки, доступные размеры, желаемую надпись и цвет. Питание, безопасность, конструкция и монтаж должны быть проверены до изготовления.</p></div></div><div class="draft-rules"><b>Никаких скрытых обязательств</b>Здесь не обещаются бесплатный макет, неограниченные правки, срок изготовления или фиксированная доставка. Это нужно утвердить для реального заказа. Контакты, персональные данные и файлы логотипов сейчас не принимаются.</div><div class="button-row"><a href="#/catalog" class="button dark">Выбрать предмет ↗</a><a href="#/account/orders" class="button secondary">Посмотреть демо-заказы</a></div></section>`;}
const COMPLEMENTS={
'roll-stand':[['squeegee-organizer','Отдельное место для ракелей рядом с рабочей зоной'],['towel-holder','Для организации микрофибры']],
'wall-roll-stand':[['brush-holder','Дополняет организацию рабочей зоны'],['squeegee-organizer','Для размещения ракелей']],
'aluminium-poster':[['neon-sign','Световой акцент рядом с автоартом'],['desk-clock','Небольшая деталь интерьера']],
'modular-panel':[['neon-sign','Для светового акцента в композиции'],['brand-poster','Чтобы добавить логотип студии']],
'nfc-stand':[['business-card-holder','Для печатных карточек на приёмке'],['care-cards','Памятка клиенту после выдачи']],
'neon-sign':[['modular-panel','Автоарт для стены студии'],['zone-sign','Навигация в том же пространстве']],
'brush-holder':[['towel-holder','Организация соседней рабочей зоны'],['squeegee-organizer','Для другого набора инструментов']],
'care-cards':[['business-card-holder','Для размещения карточек'],['nfc-stand','Для цифрового контакта со студией']]
};let recommendationShown=false,recommendationOpener=null;
function recommendationsFor(id){const pairs=COMPLEMENTS[id]||[['nfc-stand','Цифровой контакт на приёмке'],['aluminium-poster','Декоративный акцент для студии']];return pairs.filter(([pid])=>pid!==id&&!state.cart.some(x=>x.id===pid)).slice(0,2);}
function showRecommendationPrompt(id){const el=$('#toast');el.innerHTML=esc(P.find(p=>p.id===id).name)+' добавлен. <button class="toast-button" data-open-recommend="'+id+'">Подобрать дополнение</button> <a href="#/cart">В корзину ↗</a>';rewriteLinks();}
function openRecommendations(id,opener=document.activeElement){clearTimeout(toastTimer);recommendationOpener=opener;const pairs=recommendationsFor(id);if(!pairs.length){toast('Все предложенные дополнения уже в корзине.');return;}const dialog=$('#recommend-dialog');$('#recommend-content').innerHTML=`<div class="section-kicker">МОЖНО ДОПОЛНИТЬ КОМПЛЕКТ</div><h2 id="recommend-title">ЕЩЁ ОДНА<br><em>ПОЛЕЗНАЯ ДЕТАЛЬ.</em></h2><p class="recommend-note">Подборка по назначению, не статистика покупок. Совместимость, размеры и цвет согласуются отдельно. Всё можно пропустить.</p><div class="recommend-grid">${pairs.map(([pid,reason])=>{const p=P.find(p=>p.id===pid);return `<article><a href="#/product/${pid}" class="recommend-image">${visual(p)}</a><h3>${p.name}</h3><p>${reason}</p><div class="product-price-row"><div><b>${money(p.price)}</b><small>Базовое исполнение · демоцена</small></div><button class="button small" data-recommend-add="${pid}">Добавить</button></div></article>`;}).join('')}</div><div class="button-row"><button class="button secondary" data-close-recommend>Продолжить выбирать</button><a href="#/cart" class="button dark">Перейти в корзину ↗</a></div>`;recommendationShown=true;dialog.returnValue='';dialog.showModal();document.body.classList.add('modal-open');rewriteLinks();}

const ORDER_STATUS={created:'Ожидает демомакет',proof_review:'Макет на согласовании',changes_requested:'Запрошены правки',approved:'Макет согласован',production:'Демо: производство',quality_check:'Демо: проверка',ready:'Демо: готов к передаче',completed:'Демо завершено',refunded:'Демо-возврат'};
function creditPoints(amount){const repay=Math.min(state.bonusDebt||0,amount);state.bonusDebt=(state.bonusDebt||0)-repay;state.points+=amount-repay;}
function orderDetailPage(id){const raw=state.orders.find(o=>o.id===id);if(!raw)return notFound();const o=M.normalizeOrder(raw),l=o.lifecycle,review=l.status==='proof_review',canChange=['proof_review','approved'].includes(l.status),proof=l.proofs.find(p=>p.version===l.proofVersion),stageIndex=l.status==='changes_requested'?1:['created','proof_review','approved','production','quality_check','ready','completed'].indexOf(l.status);return `<section class="page order-detail">${bread('Заказ / макет / этапы')}<div class="page-head"><div><div class="section-kicker">ЛОКАЛЬНЫЙ ДЕМО-ЗАКАЗ / ${esc(o.id)}</div><h1>КАЖДАЯ ДЕТАЛЬ.<br><em>ПОД КОНТРОЛЕМ.</em></h1><p>Макет и этапы здесь условные. Согласование не отправляет заказ в производство и не создаёт юридических обязательств.</p></div><a href="#/account/orders" class="text-link">← Все демо-заказы</a></div><div class="order-status-bar"><strong>${ORDER_STATUS[l.status]}</strong><span>${l.proofVersion?'Текущая версия: V'+l.proofVersion:'Макет пока не создан'} ${l.approvedVersion?' / согласована V'+l.approvedVersion:''}</span></div><ol class="production-timeline">${[['created','Заказ'],['proof_review','Макет'],['approved','Согласование'],['production','Производство'],['quality_check','Проверка'],['ready','Готовность'],['completed','Завершение']].map(([key,label],i)=>`<li class="${i<=stageIndex?'reached':''} ${key===l.status?'current':''}"><i>${i+1}</i><span>${label}</span></li>`).join('')}</ol><div class="proof-layout"><div><section class="proof-card"><div class="section-kicker">ДЕМОПРЕДПРОСМОТР / НЕ ПРОИЗВОДСТВЕННЫЙ ФАЙЛ</div>${l.proofVersion&&l.status!=='changes_requested'?`<div class="proof-art version-${l.proofVersion%2}"><div class="proof-version">V${l.proofVersion} / ${esc(o.id)}</div><img src="assets/logo.png" alt="Логотип GTA на условном макете"><strong>ДЕМО-СТУДИЯ 01</strong><span>TOOLS / ART / ATTITUDE</span><small>УСЛОВНАЯ КОМПОЗИЦИЯ · РАЗМЕРЫ НЕ УТВЕРЖДЕНЫ</small></div><p class="proof-caption">${proof?.note?esc(proof.note):'Вымышленный макет показывает механику версий. Не является готовым макетом твоего изделия.'}</p>`:`<div class="proof-empty"><span>V${l.proofVersion||'—'}</span><h2>${l.status==='changes_requested'?'ПРАВКИ ОЖИДАЮТ<br>НОВОГО ПРОСМОТРА.':'МАКЕТ ЕЩЁ<br>НЕ ПОДГОТОВЛЕН.'}</h2><p>${l.status==='changes_requested'?'Следующий демомакет появится после действия в пульте сценария ниже. Предыдущее согласование снято.':'В реальном процессе здесь работал бы дизайнер. В прототипе ты можешь имитировать подготовку макета отдельной кнопкой.'}</p></div>`}</section>${review||canChange?`<section class="customer-proof-actions"><div class="section-kicker">ДЕЙСТВИЯ КЛИЕНТА В ДЕМО</div><h2>Проверяем версию V${l.proofVersion}</h2><form id="proof-comment-form" data-order-id="${esc(o.id)}" data-version="${l.proofVersion}"><label class="field">Тестовый комментарий к макету<textarea id="proof-comment" maxlength="600" placeholder="Например: сместить логотип выше. Не указывай реальные контакты или персональные данные."></textarea></label><div class="button-row"><button type="submit" class="button secondary">Запросить правки V${l.proofVersion}</button></div><p id="proof-error" class="error-note" role="alert" hidden></p></form>${review?`<label class="check-label"><input id="proof-confirm" type="checkbox"><span>Я посмотрел именно демомакет V${l.proofVersion}. Понимаю, что это локальная проверка сценария, а не заказ реального производства.</span></label><button class="button dark" data-approve-proof="${esc(o.id)}" data-proof-version="${l.proofVersion}">Согласовать демомакет V${l.proofVersion} ↗</button>`:'<p class="form-note">Версия согласована. До начала симуляции производства можно запросить правки: согласование будет отменено.</p>'}</section>`:''}<section class="proof-comments"><h2>Комментарии и версии</h2>${l.comments.length?l.comments.map(c=>`<article><b>К версии V${c.forVersion||c.version} → новая V${c.version}</b><p>${esc(c.text)}</p><small>Тестовый комментарий · только в этом браузере</small></article>`).join(''):'<p class="fineprint">Комментариев пока нет. Все заметки локальные, ни дизайнеру, ни продавцу они не отправляются.</p>'}${l.proofs.length?`<div class="version-list">${l.proofs.map(p=>`<span>V${p.version} / ${{draft:'черновик',review:'на проверке',approved:'согласована',superseded:'заменена'}[p.status]}</span>`).join('')}</div>`:''}</section></div><aside><section class="order-facts"><h2>Состав и расчёт</h2>${o.items.map(x=>`<div class="order-fact-row"><span>${esc(x.name)}<small>${esc(x.variant)} / ${esc(x.color)} × ${x.qty}</small></span><b>${money(x.unit*x.qty)}</b></div>`).join('')}<div class="summary-row"><span>Товары до скидок</span><b>${money(o.subtotal)}</b></div>${o.pricing?.commercialDiscount?`<div class="summary-row"><span>Сценарная скидка</span><b>−${money(o.pricing.commercialDiscount)}</b></div>`:''}<div class="summary-row"><span>Демобонусы</span><b>−${money(o.spent)}</b></div><div class="summary-row total"><span>Демо-итог</span><b>${money(o.total)}</b></div><p class="fineprint">Доставка не рассчитана. Цены зафиксированы для этой симуляции. При демо-возврате используются доли исходного расчёта, без пересчёта порога на оставшиеся товары.</p><button class="button small secondary" data-reorder="${esc(o.id)}">Повторить состав ↗</button></section><section class="demo-operator"><div class="section-kicker">ПУЛЬТ ДЕМОНСТРАЦИИ / НЕ ДЕЙСТВИЯ ЦЕХА</div><h2>Проверить следующий шаг</h2><p>Эти кнопки имитируют работу дизайнера и производства. Они не отражают физическое выполнение и ничего не передают на сервер.</p>${['created','changes_requested'].includes(l.status)?`<button class="button small" data-submit-proof="${esc(o.id)}">${l.status==='changes_requested'?'Показать новую демоверсию':'Подготовить демомакет V1'}</button>`:''}${!['created','changes_requested','completed','refunded'].includes(l.status)?`<button class="button small" data-advance-order="${esc(o.id)}" ${M.canAdvanceProduction(o)?'':'disabled'}>${{approved:'Имитировать начало производства',production:'Имитировать проверку изделия',quality_check:'Имитировать готовность',ready:'Имитировать завершение'}[l.status]||'Сначала согласуй текущий макет'}</button>`:''}${l.status==='completed'?'<p class="form-note">Сценарий завершён. Физическое изготовление, отправка и оплата не выполнялись.</p>':''}${!o.refunded?`<button class="link-button" data-refund-order="${esc(o.id)}">Имитировать полный возврат</button>`:'<p>Возврат смоделирован. Деньги не переводились; дальнейшие этапы заблокированы.</p>'}</section><section class="history-log"><h2>Ход демонстрации</h2>${l.history.length?l.history.slice().reverse().map(h=>`<div><b>${{proof_submitted:'Макет показан',proof_approved:'Версия согласована',changes_requested:'Запрошены правки',production_advanced:ORDER_STATUS[h.status],order_refunded:'Демо-возврат'}[h.type]||'Локальное событие'}</b><small>${h.version?'V'+h.version+' · ':''}${new Date(h.at).toLocaleString('ru-RU')}</small></div>`).join(''):'<p class="fineprint">Пока создан только локальный состав заказа.</p>'}</section></aside></div></section>`;}
function replaceOrder(id,updated){const i=state.orders.findIndex(o=>o.id===id);if(i>=0)state.orders[i]=updated;save();rerender();}
function errorFromModel(err){return {STALE_PROOF:'Версия изменилась. Открой актуальный макет и проверь его заново.',COMMENT_REQUIRED:'Добавь тестовый комментарий о правках.',APPROVAL_REQUIRED:'Сначала согласуй точную текущую версию макета.',ORDER_REFUNDED:'После демо-возврата этапы заблокированы.',PROOF_LOCKED:'В этой симуляции изменения после начала производства недоступны.'}[err.code]||'Не удалось выполнить действие. Обнови страницу заказа и проверь текущий этап.';}

function about(){return `<section class="page dark-page">${bread('О бренде')}<div class="about-hero"><div><div class="section-kicker">GTA / GARAGE TOOLS & ART</div><h1>ИНСТРУМЕНТЫ.<br>ИСКУССТВО.<br><em>ТВОЙ ХАРАКТЕР.</em></h1><p>GTA — оснащение и оформление для детейлинг-студий. От стойки, которая наводит порядок, до арт-объекта, который узнают с порога.</p><p>Собираем пространство вокруг твоей команды, твоего логотипа и твоего подхода к работе.</p><a href="#/catalog" class="button">Познакомиться с коллекцией ↗</a></div><img src="assets/crew.png" alt="Команда маскотов GTA: мастера детейлинга"></div><div class="about-grid"><div><b>01</b><h2>Для работы.</h2><p>Стойки, системы организации, NFC- и QR-носители. Вещи с понятной задачей в рабочем пространстве.</p></div><div><b>02</b><h2>Для впечатления.</h2><p>Алюминиевые постеры A3 и A4, панно из 3, 6 и 9 элементов, свет и объёмные детали.</p></div><div><b>03</b><h2>Для твоего имени.</h2><p>Дизайн под студию: логотип, цвет, композиция, печатные материалы. Каждая деталь обсуждается отдельно.</p></div></div><div class="home-partner" style="color:var(--navy);margin:0"><div><div class="section-kicker">ПАРТНЁРСКИЕ ПРОЕКТЫ</div><h2>СОБИРАЕМ<br>БОЛЬШЕ ВМЕСТЕ.</h2><p>Отдельное направление с FIVEROX: проекты предложений по оснащению студий. Условия ещё согласуются.</p><a href="#/fiverox" class="button dark">GTA × FIVEROX ↗</a></div><div class="partner-wordmark">FIVE<span>ROX</span><small>ПАРТНЁРСКОЕ НАПРАВЛЕНИЕ</small></div></div></section>`;}
function legal(){return `<section class="page">${bread('Информация и документы')}<div class="page-head"><div><div class="section-kicker">ПРОЗРАЧНО О ТЕКУЩЕЙ ВЕРСИИ</div><h1>ПЕРЕД ЗАПУСКОМ.</h1><p>Этот раздел показывает, что уже есть в прототипе и что должно быть согласовано для настоящего магазина.</p></div>${tag('Проект · не оферта')}</div><div class="legal-layout"><aside><strong>Продавец</strong><br>Андрющенко Т.Ю. · самозанятость<br><br>ИНН, полное имя, контакты и адрес для обращений не предоставлены. До запуска нужно добавить подтверждённые сведения.</aside><article><section><h2>01 / Статус магазина</h2><p>Это интерактивная демонстрация интерфейса. Цены и бонусные суммы вымышленные. Изображения показывают концепты изделий. Реальные продажи, наличие, сроки производства и оплаты здесь не представлены.</p></section><section><h2>02 / Заказ, оплата и доставка</h2><p>Оформление сохраняет пример заказа только в браузере. Ни продавец, ни платёжный сервис его не получают. Тарифы доставки не рассчитаны и не включены в демосуммы. Требуется согласовать реальные способы оплаты, сроки, географию и стоимость доставки.</p></section><section><h2>03 / Возврат и обращения</h2><p>Условия возврата, отмены, претензий и персонализированных изделий должны быть подготовлены и проверены до запуска. Здесь нет действующего документа, юридических гарантий или замены применимых прав покупателя.</p></section><section><h2>04 / Данные в этой демонстрации</h2><p>В браузерном localStorage сохраняются выбранные товары, исполнения, количество, избранное, вымышленный профиль, локальная история и демобаллы. Реальные имя, email, телефон, адрес и платёжные данные не запрашиваются. На разных устройствах состояние не синхронизируется.</p><p>Можно удалить демоданные кнопкой ниже. Это очистит только состояние GTA-демо в этом браузере. Очистка браузера также может удалить сохранённое состояние. У хостинга сайта могут быть собственные технические механизмы доступа и журналы, которые не контролируются этим прототипом.</p><button class="button secondary small" data-action="reset-demo">Удалить локальные демоданные</button></section><section><h2>05 / Бонусы, рекомендации и FIVEROX</h2><p>Программа лояльности, реферальная механика и партнёрские подарки — отдельные проекты условий. Они не действуют и не создают права на реальные выплаты, скидки или подарки. GTA не продаёт плёнку. Получатель будущих партнёрских заявок и порядок согласия на передачу данных должны быть подтверждены.</p></section><section><h2>06 / Документы для рабочей версии</h2><ul><li>Подтверждённые сведения продавца и контакты</li><li>Условия заказа и персонализации</li><li>Оплата, доставка, возврат и претензии</li><li>Политика обработки персональных данных и нужные согласия</li><li>Утверждённые правила бонусной и реферальной программ</li><li>Отдельные согласованные условия программ FIVEROX</li></ul><p>Этот перечень — рабочий список, а не утверждённый юридический пакет.</p></section></article></div></section>`;}
function notFound(){return `<section class="page"><div class="empty-state"><div class="empty-symbol">404</div><h2>ЭТОГО ПОВОРОТА НЕТ.</h2><p>Страница или демо-заказ не найдены. Вернёмся к деталям, которые есть.</p><a href="#/catalog" class="button dark">В магазин ↗</a></div></section>`;}
function referralLink(){const u=new URL(location.href);u.hash='/catalog?ref=GTA-DEMO';u.search='';return u.href;}
// Anchor the site root once. Browser history can move between differently nested pages.
const siteBase = location.protocol === 'file:' || window.GTA_STANDALONE
  ? null
  : new URL(document.baseURI);
if (siteBase) $('base').href = siteBase.href;

function routeURL(path) {
  if (!siteBase) return '#'+path;
  const [route, query = ''] = path.split('?');
  if (route.startsWith('/order/')) {
    return siteBase.pathname+'account/orders/?order='+encodeURIComponent(route.split('/')[2]);
  }
  if (route.startsWith('/success/')) {
    return siteBase.pathname+'checkout/?result='+encodeURIComponent(route.split('/')[2]);
  }
  const page = route.replace(/^\/product\//, '/products/');
  const relative = page === '/' ? '' : page.slice(1).replace(/\/$/, '')+'/';
  return siteBase.pathname+relative+(query ? '?'+query : '');
}

function routePath() {
  if (location.hash?.startsWith('#/')) return location.hash.slice(1);
  if (!siteBase) return '/';
  const relative = location.pathname.slice(siteBase.pathname.length);
  const page = '/'+relative.replace(/index\.html$/, '').replace(/\/$/, '');
  const query = new URLSearchParams(location.search || '');
  if (page === '/account/orders' && query.has('order')) return '/order/'+query.get('order');
  if (page === '/checkout' && query.has('result')) return '/success/'+query.get('result');
  return page.replace(/^\/products\//, '/product/')+(query.size ? '?'+query.toString() : '');
}
function rewriteLinks(){for(const a of $$('a[href]')){const raw=a.getAttribute('href');if(raw?.startsWith('#/')){a.dataset.route=raw.slice(1);a.setAttribute('data-route',raw.slice(1));a.setAttribute('href',routeURL(raw.slice(1)));}}}
let currentRouteKey='';
function route(options={}){const full=routePath(),[path,query='']=full.split('?'),params=new URLSearchParams(query),parts=path.split('/').filter(Boolean),type=parts[0]||'home';if($('#recommend-dialog')?.open)$('#recommend-dialog').close('navigation');$$('.nav-more,.mobile-menu').forEach(n=>n.open=false);renderedRoute=path;currentRouteKey=full;document.body.classList.toggle('home-route',type==='showcase');$('#home-view').hidden=type!=='showcase';if(type!=='showcase')$('#home-view').innerHTML='';$('#page-view').hidden=type==='showcase';$$('[data-nav]').forEach(a=>a.classList.toggle('active',a.dataset.nav===type));let html='';
if(type==='showcase'){$('#home-view').innerHTML=GTA_SHOWCASE;$('#home-products').innerHTML=P.slice(0,4).map(productCard).join('');document.title='GTA · Вау-презентация детейлинг-студии';}
else if(type==='home'){html=homePage();document.title='GTA — оснащение и декор для детейлинг-студий';}
else if(type==='catalog'){lastCatalogRoute=full;filter.category=params.get('category')||'all';if(!C.some(([id])=>id===filter.category))filter.category='all';filter.q=params.get('q')||'';filter.sort=params.get('sort')||'featured';filter.favorites=params.get('favorites')==='1';html=catalog();document.title='Каталог оснащения и декора для детейлинга | GTA';}
else if(type==='product'){html=productPage(parts[1]);document.title=(P.find(p=>p.id===parts[1])?.name||'Не найдено')+' для детейлинг-студии | GTA';}
else if(type==='cart'){html=cartPage();document.title='Корзина · GTA';}
else if(type==='checkout'){checkoutBusy=false;html=checkoutPage();document.title='Демооформление · GTA';}
else if(type==='success'){html=successPage(parts[1]);document.title='Демо-заказ создан · GTA';}
else if(type==='order'){html=orderDetailPage(parts[1]);document.title='Демомакет и этапы заказа · GTA';}
else if(type==='fiverox'){html=fiverox();document.title='GTA × FIVEROX · Проект партнёрских программ';}
else if(type==='account'){html=state.member||params.get('guest')==='1'?accountPage(parts[1]||'',params.get('guest')==='1'):loginPage(params.get('next')||`account${parts[1]?'/'+parts[1]:''}`);document.title='Мой гараж · GTA · Демо';}
else if(type==='kit'){html=kitPage();document.title='Собрать комплект для детейлинг-студии | GTA';}
else if(type==='how-it-works'){html=howItWorks();document.title='Как согласовать макет и заказать оснащение | GTA';}
else if(type==='collaborations'){calculatorMode='simple';html=collaborationPage();document.title='GTA CREW · Коллаборации и калькулятор';}
else if(type==='about'){html=about();document.title='О GTA Garage Tools & Art';}
else if(type==='legal'){html=legal();document.title='Информация и документы · GTA';}
else html=notFound();
if(type!=='showcase')$('#page-view').innerHTML=html;if(type==='catalog')updateCatalog();if(type==='collaborations')updateCalculator();if(type==='kit')updateKit();updateHeader();rewriteLinks();window.scrollTo({top:options.restore?(scrollPositions[full]||0):0,behavior:'instant'});$('#main').focus({preventScroll:true});if(type==='fiverox'&&params.get('section')==='programs')requestAnimationFrame(()=>$('#programs').scrollIntoView({behavior:'smooth'}));if(type==='collaborations'&&['calculator','creator-request'].includes(params.get('section')))requestAnimationFrame(()=>$('#'+params.get('section')).scrollIntoView({behavior:'smooth'}));requestScroll();}
function rerender(){const y=window.scrollY;route();window.scrollTo({top:y,behavior:'instant'});}
function go(path,restore=false){const p=path.startsWith('/')?path:'/'+path;scrollPositions[currentRouteKey]=window.scrollY;if(location.protocol==='file:'||window.GTA_STANDALONE){if(location.hash==='#'+p)route({restore});else{location.hash=p;}}else{history.pushState(null,'',routeURL(p));route({restore});}}
function confirmAction(title,description,button,cb){pendingConfirmation=cb;$('#confirm-title').textContent=title;$('#confirm-description').textContent=description;$('#confirm-dialog button[value="confirm"]').textContent=button;$('#confirm-dialog').returnValue='';$('#confirm-dialog').showModal();document.body.classList.add('modal-open');}
$('#confirm-dialog').addEventListener('cancel',()=>{$('#confirm-dialog').returnValue='cancel';pendingConfirmation=null;});
$('#confirm-dialog').addEventListener('close',()=>{document.body.classList.remove('modal-open');const cb=pendingConfirmation;pendingConfirmation=null;if($('#confirm-dialog').returnValue==='confirm'&&cb)cb();});
$('#recommend-dialog').addEventListener('close',()=>{document.body.classList.remove('modal-open');recommendationShown=true;const navigation=$('#recommend-dialog').returnValue==='navigation';if(!navigation){if(renderedRoute==='/cart')rerender();const opener=recommendationOpener;if(opener?.isConnected&&opener.getClientRects().length&&!opener.hidden)opener.focus({preventScroll:true});else $('.cart-link').focus({preventScroll:true});}recommendationOpener=null;});$('#recommend-dialog').addEventListener('click',e=>{if(e.target===$('#recommend-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close('dismiss')}});
$('#confirm-dialog').addEventListener('click',e=>{if(e.target===$('#confirm-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close('cancel')}});
function addProduct(p,v=0,color=p.colors[0],qty=1){M.add(state,{id:p.id,v,color,qty});save();toast(`${p.name} добавлен в демо-корзину`,'#/cart');if(!recommendationShown)showRecommendationPrompt(p.id);}
document.addEventListener('click',async e=>{const nav=e.target.closest('a[data-route]');if(nav&&!e.ctrlKey&&!e.metaKey&&!e.shiftKey&&!e.altKey){e.preventDefault();go(nav.dataset.route,nav.dataset.route===lastCatalogRoute);return;}if(e.target.closest('.skip')){e.preventDefault();$('#main').focus();return;}const openRec=e.target.closest('[data-open-recommend]');if(openRec){openRecommendations(openRec.dataset.openRecommend,openRec);return;}if(e.target.closest('[data-close-recommend]')){$('#recommend-dialog').close('dismiss');return;}const recAdd=e.target.closest('[data-recommend-add]');if(recAdd){const p=P.find(p=>p.id===recAdd.dataset.recommendAdd);addProduct(p);recAdd.disabled=true;recAdd.textContent='Добавлено';return;}const quick=e.target.closest('[data-quick]');if(quick){addProduct(P.find(p=>p.id===quick.dataset.quick));return;}const fav=e.target.closest('[data-favorite]');if(fav){const id=fav.dataset.favorite;if(state.favorites.includes(id))state.favorites=state.favorites.filter(x=>x!==id);else state.favorites.push(id);save();if(renderedRoute==='/catalog')updateCatalog();else if(renderedRoute==='/account/favorites')rerender();else{$$(`[data-favorite="${id}"]`).forEach(b=>{const on=state.favorites.includes(id);b.classList.toggle('selected',on);b.textContent=on?'♥':'♡';b.setAttribute('aria-pressed',on);b.setAttribute('aria-label',`${on?'Убрать из':'Добавить в'} избранное: ${P.find(p=>p.id===id).name}`)})}return;}
const calcMode=e.target.closest('[data-calc-mode]');if(calcMode){calculatorMode=calcMode.dataset.calcMode;$$('[data-calc-mode]').forEach(b=>{b.classList.toggle('selected',b===calcMode);b.setAttribute('aria-pressed',b===calcMode)});$('#simple-inputs').hidden=calculatorMode!=='simple';$('#funnel-inputs').hidden=calculatorMode!=='funnel';updateCalculator();return;}
const fil=e.target.closest('[data-filter]');if(fil){filter.category=fil.dataset.filter;updateCatalog();return;}
const variant=e.target.closest('[data-variant]');if(variant){detail.v=Number(variant.dataset.variant);$$('[data-variant]').forEach(b=>{b.classList.toggle('selected',b===variant);b.setAttribute('aria-pressed',b===variant)});const p=P.find(p=>p.id===$('.detail-info').dataset.product);$('#detail-price').textContent=money(p.price+p.variants[detail.v][1]);return;}
const color=e.target.closest('[data-color]');if(color){detail.color=color.dataset.color;$$('[data-color]').forEach(b=>{b.classList.toggle('selected',b===color);b.setAttribute('aria-pressed',b===color)});return;}
const dq=e.target.closest('[data-detail-qty]');if(dq){detail.qty=M.integer(detail.qty+Number(dq.dataset.detailQty),1,99);$('#detail-quantity').textContent=detail.qty;return;}
const add=e.target.closest('[data-add-detail]');if(add){addProduct(P.find(p=>p.id===add.dataset.addDetail),detail.v,detail.color,detail.qty);return;}
const cq=e.target.closest('[data-cart-qty]');if(cq){const i=Number(cq.dataset.cartQty);state.cart[i].qty=M.integer(state.cart[i].qty+Number(cq.dataset.delta),1,99);save();rerender();const focus=$(`[data-cart-qty="${i}"][data-delta="${cq.dataset.delta}"]`);focus?.focus({preventScroll:true});return;}
const rm=e.target.closest('[data-remove]');if(rm){state.cart.splice(Number(rm.dataset.remove),1);save();rerender();toast('Предмет убран из демо-корзины');return;}
const login=e.target.closest('[data-login]');if(login){state.member=true;save();go(login.dataset.login);toast('Открыт вымышленный профиль. Реального входа нет.');return;}
const program=e.target.closest('[data-program]');if(program){$('#partner-program').value=program.dataset.program;$('#partner-request').scrollIntoView({behavior:'smooth',block:'center'});$('#partner-program').focus({preventScroll:true});return;}
const reorder=e.target.closest('[data-reorder]');if(reorder){const o=state.orders.find(o=>o.id===reorder.dataset.reorder);let added=0;for(const x of o?.items||[]){const p=P.find(p=>p.id===x.id)||P.find(p=>p.name===x.name);if(!p)continue;const v=Math.max(0,p.variants.findIndex(a=>a[0]===x.variant));M.add(state,{id:p.id,v,color:p.colors.includes(x.color)?x.color:p.colors[0],qty:x.qty});added++;}save();toast(added?'Состав добавлен по текущим демоценам':'Предметы больше не найдены в каталоге',added?'#/cart':'');return;}
const refund=e.target.closest('[data-creator-refund]');if(refund){const o=state.creator.orders.find(o=>o.id===refund.dataset.creatorRefund);if(o&&!o.refunded){o.refunded=true;save();rerender();toast('Демо-возврат: комиссия сторнирована. Реальной выплаты не было.');}return;}
const submitProof=e.target.closest('[data-submit-proof]');if(submitProof){const o=state.orders.find(o=>o.id===submitProof.dataset.submitProof);try{replaceOrder(o.id,M.submitProof(o,{note:'Условный макет для проверки версий. Правки не исполняются дизайнером автоматически.',at:Date.now()}));}catch(err){toast(errorFromModel(err));}return;}
const approve=e.target.closest('[data-approve-proof]');if(approve){if(!$('#proof-confirm').checked){$('#proof-error').hidden=false;$('#proof-error').textContent='Подтверди просмотр точной версии демомакета.';$('#proof-confirm').focus();return;}const o=state.orders.find(o=>o.id===approve.dataset.approveProof);try{replaceOrder(o.id,M.approveProof(o,Number(approve.dataset.proofVersion),{at:Date.now()}));toast('Точная версия согласована только в локальном демо.');}catch(err){toast(errorFromModel(err));}return;}
const advance=e.target.closest('[data-advance-order]');if(advance){const o=state.orders.find(o=>o.id===advance.dataset.advanceOrder);try{const next=M.advanceProduction(o,{at:Date.now()});if(next.done&&!o.done){state.pending=Math.max(0,state.pending-o.earned);creditPoints(o.earned);if(o.earned)state.ledger.unshift({label:'Начисление за '+o.id,amount:o.earned,note:'После завершения всех демоэтапов'});}replaceOrder(o.id,next);toast('Переключён только демонстрационный этап. Физическая работа не выполнена.');}catch(err){toast(errorFromModel(err));}return;}
const refundOrder=e.target.closest('[data-refund-order]');if(refundOrder){const id=refundOrder.dataset.refundOrder;confirmAction('Имитировать полный возврат?','Демокомплект получит статус возврата, этапы заблокируются, демобаллы будут скорректированы по исходному расчёту. Реального перевода денег нет.','Имитировать возврат',()=>{const o=state.orders.find(o=>o.id===id);try{const next=M.refundOrder(o,{at:Date.now()});creditPoints(o.spent);if(o.done){const taken=Math.min(state.points,o.earned);state.points-=taken;state.bonusDebt=(state.bonusDebt||0)+o.earned-taken;}else state.pending=Math.max(0,state.pending-o.earned);state.ledger.unshift({label:'Демо-возврат '+o.id,amount:o.spent-(o.done?o.earned:0),note:'Коррекция по исходному расчёту; не деньги'});replaceOrder(id,next);}catch(err){toast(errorFromModel(err));}});return;}
const action=e.target.closest('[data-action]')?.dataset.action;if(!action)return;
if(action==='show-recommendations'){openRecommendations(state.cart[0]?.id||'roll-stand');}
if(action==='creator-first'&&!state.creator.customer){state.creator.customer=true;state.creator.orders.push({id:'CREW-DEMO-1',type:'first',paid:4000,reward:800,refunded:false});save();rerender();toast('Первый вымышленный заказ: 800 ₽ демокомиссии.');}
if(action==='creator-repeat'&&state.creator.customer){const paid=$('#creator-repeat-policy').value==='always'?4000:5000;state.creator.orders.push({id:'CREW-DEMO-'+(state.creator.orders.length+1),type:'repeat',paid,reward:paid*.1,refunded:false});save();rerender();toast('Повторный вымышленный заказ: '+money(paid*.1)+' демокомиссии.');}
if(action==='add-kit'){let count=0;for(const pid of Object.values(kitState)){const p=P.find(p=>p.id===pid);if(p){M.add(state,{id:p.id,v:0,color:p.colors[0],qty:1});count++;}}if(count){save();toast('Комплект из '+count+' предметов добавлен в демо-корзину.','#/cart');}}
if(action==='reset-filters'){filter={category:'all',q:'',sort:'featured',favorites:false};if($('#catalog-search')){$('#catalog-search').value='';updateCatalog()}else go('catalog');}
if(action==='toggle-favorites'){filter.favorites=!filter.favorites;updateCatalog();}
if(action==='clear-cart')confirmAction('Очистить корзину?','Все выбранные товары будут удалены из локальной демо-корзины.','Очистить',()=>{state.cart=[];save();rerender()});
if(action==='reset-demo')confirmAction('Начать демо заново?','Удалятся локальные демо-заказы, избранное и корзина. Пример бонусного баланса вернётся к 1 200. Реальных данных здесь нет.','Сбросить демо',()=>{state=M.initial();pricingScenario='volume';useBonus=false;save();go('account');toast('Локальная демонстрация сброшена.');});
if(action==='logout'){state.member=false;useBonus=false;save();go('account');toast('Демокабинет закрыт. Корзина и история сохранены локально.');}
if(action==='copy-referral'){const input=$('#referral-link');try{if(!navigator.clipboard?.writeText)throw Error('unsupported');await navigator.clipboard.writeText(input.value);$('#copy-status').textContent='Демоссылка скопирована. Отслеживания и реального вознаграждения нет; ссылка предназначена для демонстрации.';toast('Демоссылка скопирована');}catch(err){input.focus();input.select();$('#copy-status').textContent='Автокопирование недоступно. Ссылка выделена: нажми Ctrl+C или ⌘C. Она не отслеживает приглашения.';} }
if(action==='simulate-referral'&&!state.referralDone&&state.member){state.referralDone=true;creditPoints(M.RULES.referral);state.ledger.unshift({label:'Пример приглашения студии',amount:M.RULES.referral,note:'Вымышленный первый заказ на 3 000 ₽ · один тест'});save();rerender();toast('Вымышленный сценарий: +300 демобаллов. Реального друга нет.');}
});
document.addEventListener('input',e=>{if(e.target.id.startsWith('calc-'))updateCalculator();if(e.target.id==='catalog-search'){filter.q=e.target.value;updateCatalog()}});
document.addEventListener('change',e=>{if(e.target.dataset.cartVariant!==undefined||e.target.dataset.cartColor!==undefined){const i=Number(e.target.dataset.cartVariant??e.target.dataset.cartColor),line=state.cart[i];if(e.target.dataset.cartVariant!==undefined)line.v=Number(e.target.value);else line.color=e.target.value;const lines=state.cart;state.cart=[];for(const x of lines)M.add(state,x);save();rerender();return;}if(e.target.id==='pricing-scenario'){pricingScenario=e.target.value;useBonus=false;save();$('#summary-wrap').innerHTML=summary(renderedRoute==='/checkout');rewriteLinks();return;}if(e.target.id==='creator-repeat-policy'){state.creator.policy=e.target.value==='always'?'always':'first';save();}if(e.target.dataset.kit){kitState[e.target.dataset.kit]=e.target.value;updateKit();}if(e.target.id.startsWith('calc-'))updateCalculator();if(e.target.id==='catalog-sort'){filter.sort=e.target.value;updateCatalog()}if(e.target.id==='use-bonus'){useBonus=e.target.checked;$('#summary-wrap').innerHTML=summary(renderedRoute==='/checkout');$('#use-bonus')?.focus({preventScroll:true})}});
document.addEventListener('submit',e=>{if(e.target.id==='proof-comment-form'){e.preventDefault();const form=e.target,o=state.orders.find(o=>o.id===form.dataset.orderId);try{replaceOrder(o.id,M.requestChanges(o,Number(form.dataset.version),$('#proof-comment').value,{at:Date.now()}));toast('Правки сохранены локально. Предыдущее согласование снято.');}catch(err){$('#proof-error').hidden=false;$('#proof-error').textContent=errorFromModel(err);}return;}if(e.target.id==='checkout-form'){e.preventDefault();if(checkoutBusy||!state.cart.length)return;if(!$('#demo-confirm').checked){$('#checkout-error').hidden=false;$('#checkout-error').textContent='Подтверди, что проверяешь только демосценарий. Реальный заказ и оплата не создаются.';$('#demo-confirm').focus();return;}checkoutBusy=true;const t=totals(),date=Date.now(),id=`DEMO-${date}-${state.orders.length+1}`,o={id,date,items:state.cart.map(x=>{const p=P.find(p=>p.id===x.id);return {id:p.id,v:x.v,name:p.name,variant:p.variants[x.v][0],color:x.color,qty:x.qty,unit:p.price+p.variants[x.v][1]}}),subtotal:t.subtotal,total:t.total,spent:t.spent,earned:t.earned,delivery:new FormData(e.target).get('delivery'),done:false};o.pricing=M.capturePricing(o.items,t);state.orders.unshift(M.normalizeOrder(o));state.points-=t.spent;state.pending+=t.earned;if(t.spent)state.ledger.unshift({label:'Списание в '+id,amount:-t.spent,note:'Сумма изменена только в демонстрации'});state.cart=[];useBonus=false;save();go('success/'+id);}
if(e.target.id==='creator-calculator-form'){e.preventDefault();updateCalculator();}
if(e.target.id==='creator-form'){e.preventDefault();const result=$('#creator-result');result.hidden=false;if(!$('#creator-category').value){result.textContent='Выбери направление для проверки примера.';$('#creator-category').focus();return;}if(!$('#creator-confirm').checked){result.textContent='Подтверди, что это только демозаявка.';$('#creator-confirm').focus();return;}result.style.color='#3c7a70';result.textContent='Демозаявка проверена. Ничего не отправлено, не сохранено, комплект не забронирован. Реальные условия и сотрудничество не оформлены.';}
if(e.target.id==='partner-form'){e.preventDefault();const result=$('#partner-result');result.hidden=false;if(!$('#partner-program').value){result.textContent='Выбери программу для проверки сценария.';$('#partner-program').focus();return;}if(!$('#partner-confirm').checked){result.textContent='Подтверди, что понимаешь демонстрационный режим.';$('#partner-confirm').focus();return;}result.style.color='#3c7a70';result.textContent=`Проверка пройдена: ${$('#partner-program').value}. Ничего не отправлено GTA или FIVEROX. Данные не сохранены. Условия программы требуют подтверждения.`;}
});
addEventListener('storage',e=>{if(e.key!==KEY)return;try{state=e.newValue?M.sanitize(JSON.parse(e.newValue),P):M.initial();rerender();toast('Локальное демо обновлено из другой вкладки.')}catch{toast('Не удалось прочитать изменение из другой вкладки.')}});
const reduce=matchMedia('(prefers-reduced-motion: reduce)');let pendingScroll=false;
function updateScroll(){pendingScroll=false;const cr=$('.compact-crew');if(cr&&!reduce.matches){cr.style.transform=`translateY(${Math.min(window.scrollY*.08,35)}px)`;}if($('#home-view').hidden)return;const track=$('#scroll-track'),stage=$('#stage');if(!track)return;const span=track.offsetHeight-innerHeight,p=GTAScroll.clamp(-track.getBoundingClientRect().top/Math.max(1,span)),s=GTAScroll.state(reduce.matches?0:p);$('#crew').style.transform=`translateX(${s.crewX}vw)`;$('#crew').style.opacity=s.crewOpacity;$('#rack').style.transform=`translate(${s.rackX}vw,${s.rackY}vh) scale(${s.rackScale})`;$('#rack').style.opacity=s.rackOpacity;$('#art').style.transform=`translate(${s.artX}vw,${s.artY}vh) scale(${s.artScale})`;$('#art').style.opacity=s.artOpacity;$('#light').style.transform=`translateX(${s.lightX}vw)`;$('#light').style.opacity=s.lightOpacity;$('#backdrop').style.transform=`scale(${s.backdropScale})`;$('#progress').style.transform=`scaleX(${p})`;$('#percent').textContent=String(Math.round(p*100)).padStart(2,'0')+'%';$('#chapter').textContent=['ЛИСТАЙ. СОБИРАЙ СВОЙ ДЕТЕЙЛИНГ.','01 / ОСНАЩЕНИЕ ТВОЕГО ДЕТЕЙЛИНГА','02 / АВТОАРТ ДЛЯ ТВОЕГО ДЕТЕЙЛИНГА','03 / СВЕТ ДЛЯ ТВОЕГО ДЕТЕЙЛИНГА'][s.chapter];stage.dataset.chapter=s.chapter;}
function requestScroll(){if(!pendingScroll){pendingScroll=true;requestAnimationFrame(updateScroll)}}
function preference(){document.body.classList.toggle('no-motion',reduce.matches);requestScroll()}
addEventListener('scroll',requestScroll,{passive:true});addEventListener('resize',requestScroll);reduce.addEventListener('change',preference);addEventListener('hashchange',()=>route());addEventListener('popstate',()=>route({restore:true}));preference();route();
})();
